23	/** A claim by a person on a sheet: an amount (two decimals), a date, a note, a status and, once opened,
24	 *  a number and who opened it. A negative amount is a correction, naming the number of the claim it corrects. */
25	@Entity
26	@EntityListeners(History.class)
27	@Table(name = "claim")
28	public class Claim {
29	
30	    @Id
31	    @GeneratedValue(strategy = GenerationType.IDENTITY)
32	    private Long id;
33	
34	    @Column(name = "sheet_id", nullable = false)
35	    private String sheetId;
36	
37	    @Column(name = "person_id", nullable = false)
38	    private Long personId;
39	
40	    /** Its place in the sheet's list, newest (highest) first: set when added, and again when reassigned. */
41	    @Column(name = "list_order", nullable = false)
42	    private long listOrder;
43	
44	    @Column(name = "amount", nullable = false)
45	    private BigDecimal amount;
46	
47	    @Column(name = "claim_date", nullable = false)
48	    private LocalDate date;
49	
50	    /** The day it is due by: fixed when it is added, from the terms of its person's grade in force on its
51	     *  date then, counted as that many business days after its date (skipping weekends and the sheet's
52	     *  holidays listed then); it does not follow later changes to the terms or its date. Adding a holiday
53	     *  works it out again, with the same terms, while the claim is not SETTLED or VOID. */
54	    @Column(name = "due_by", nullable = false)
55	    private LocalDate dueBy;
56	
57	    /** The terms its due-by was fixed with: that many business days after its date. */
58	    @Column(name = "terms", nullable = false)
59	    private int terms;
60	
61	    @Column(name = "note", nullable = false)
62	    private String note;
63	
64	    @Enumerated(EnumType.STRING)
65	    @Column(name = "status", nullable = false)
66	    private ClaimStatus status = ClaimStatus.DRAFT;
67	
68	    /** A correction's: the number of the SETTLED claim of the same person it corrects; none otherwise. */
69	    @Column(name = "corrects_number")
70	    private String corrects;
71	
72	    /** Given when the claim is opened; none while a draft or once voided. */
73	    @Column(name = "claim_number")
74	    private String number;
75	
76	    /** Fixed when the claim is settled, if its grade had a rate then; none otherwise. */
77	    @Column(name = "settled_due")
78	    private BigDecimal settledDue;
79	
80	    /** The user who opened the claim; none while a draft. */
81	    @Column(name = "opened_by")
82	    private String openedBy;
83	
84	    /** The user who last edited the claim; none while never edited. */
85	    @Column(name = "edited_by")
86	    private String editedBy;
