93	     *  that was n/a, or unbound. */
94	    @Column(name = "stated_due")
95	    private BigDecimal statedDue;
96	
97	    /** The date an OPEN claim is deferred until; none when never deferred. */
98	    @Column(name = "deferred_until")
99	    private LocalDate deferredUntil;
100	
101	    /** How many proofs it has: raised by one at a time. */
102	    @Column(name = "proofs", nullable = false)
103	    private int proofs;
104	
105	    /** How many of its proofs are photos; the rest are receipts. */
106	    @Column(name = "proof_photos", nullable = false)
107	    private int proofPhotos;
108	
109	    /** The number of the claim it was split from; none when it was not split off another. */
