119	    private String lockedBy;
120	
121	    /** Whether it was added (or split off) while its period, the one containing its due-by, was soft-closed. */
122	    @Column(name = "late_entry", nullable = false)
123	    private boolean lateEntry;
124	
125	    /** The last day (the sheet's today then) a reminder was written for it; none when never reminded. */
126	    @Column(name = "reminded_on")
127	    private LocalDate remindedOn;
128	
129	    /** Whether a reminder escalated it; a claim is escalated once ever. */
