153	    /** Its status log: one line per status it has had, oldest first. */
154	    @ElementCollection(fetch = FetchType.EAGER)
155	    @CollectionTable(name = "claim_status_log", joinColumns = @JoinColumn(name = "claim_id"))
156	    @OrderColumn(name = "seq")
