185	    /** A copy of the claim for a person on another sheet, listed at a place there: its status, dates, note,
186	     *  terms, frozen figure, tags, status log, comments and lines carried; no number (one is given there), no figure
187	     *  a statement bound, no reference, settle batch or lock. */
188	    public Claim copyTo(String otherSheetId, Long otherPersonId, long otherListOrder) {
189	        Claim copy = new Claim(otherSheetId, otherPersonId, amount, date, dueBy, note, corrects);
190	        copy.listOrder = otherListOrder;
191	        copy.terms = terms;
192	        copy.status = status;
193	        copy.settledDue = settledDue;
194	        copy.stated = stated;
195	        copy.statedDue = statedDue;
196	        copy.openedBy = openedBy;
197	        copy.editedBy = editedBy;
198	        copy.deferredUntil = deferredUntil;
199	        copy.proofs = proofs;
200	        copy.proofPhotos = proofPhotos;
201	        copy.splitFrom = splitFrom;
202	        copy.lateEntry = lateEntry;
203	        copy.remindedOn = remindedOn;
204	        copy.escalated = escalated;
205	        copy.waived = waived;
206	        copy.held = held;
207	        copy.voidReason = voidReason;
208	        copy.tags = tags;
209	        statusLog.forEach(l -> copy.statusLog.add(new StatusChange(l.getStatus(), l.getBy(), l.getOn(), l.getDue())));
210	        comments.forEach(c -> copy.comments.add(new ClaimComment(c.getBy(), c.getOn(), c.getText())));
211	        lines.forEach(l -> copy.lines.add(new ClaimLine(l.getLabel(), l.getQty(), l.getUnit())));
212	        return copy;
213	    }
