84	
85	    /** The sheet's claims, newest first. */
86	    @Transactional(readOnly = true)
87	    public List<Claim> list(String sheetId) {
88	        sheets.today(sheetId);
89	        return claims.findBySheetIdOrderByListOrderDesc(sheetId);
90	    }
91	
92	    /** The terms in force for a claim of the person created on the day: the person's own, else those of the
93	     *  grade they had that day, else the sheet's, each as they stood that day. */
94	    private int termsOn(String sheetId, Person person, LocalDate day) {
95	        Integer own = person.termsOn(day);
96	        return own != null ? own
97	                : sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
98	                        .termsFor(person.gradeOn(day), day);
99	    }
100	
101	    /** Add a claim; a negative amount (a correction) must name a SETTLED claim of the person by number,
102	     *  and a claim of 0.00 or more must name none. A reference (none: not given) already used on the sheet
103	     *  is refused. */
104	    @Transactional
105	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
106	            String corrects, String ref, List<String> tags) {
107	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
108	        LocalDate on = date != null ? date : sheets.entryDefault(sheetId);
109	        int terms = termsOn(sheetId, person, sheets.today(sheetId));
110	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
111	        refuseClosed(sheetId, dueBy);
112	        refuseRetired(person, on);
113	        refuseCorrection(sheetId, personId, amount, corrects, null);
114	        refuseRefUsed(sheetId, ref, null);
115	        Rollup.Snapshot before = rollup.take(sheetId);
116	        Claim claim = new Claim(sheetId, personId, amount.setScale(2), on, dueBy, note, corrects);
117	        claim.setTerms(terms);
118	        claim.setRef(ref);
119	        claim.setTags(tags);
120	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
121	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
122	        logStatus(claim, person, user);
123	        claim = claims.saveAndFlush(claim);
124	        audit("CLAIM_ADDED", claim, person, user, claim.getNumber(),
125	                (claim.getRef() != null ? " ref=" + claim.getRef() : "")
126	                        + (tags.isEmpty() ? "" : " tags=" + String.join(",", tags)));
127	        recordTags(sheetId, tags);
128	        if (claim.isLateEntry()) {
129	            audit("LATE_ENTRY", claim, person, user);
130	        }
131	        rollup.recordChanges(sheetId, user, before);
132	        return claim;
133	    }
