147	    /** Change a DRAFT claim; a claim in any other status is refused, and a correction or a reference as when
148	     *  added. A claim with lines keeps the amount they add up to: another amount is refused. */
149	    @Transactional
150	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
151	            String corrects, String ref, List<String> tags) {
152	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
153	        if (claim.getStatus() != ClaimStatus.DRAFT) {
154	            throw new ClaimNotDraftException(claim.getStatus());
155	        }
156	        refuseLocked(claim, user);
157	        LocalDate on = date != null ? date : sheets.today(sheetId);
158	        refuseClosed(sheetId, claim.getDueBy());
159	        refuseRetired(people.findByIdAndSheetId(claim.getPersonId(), sheetId)
160	                .orElseThrow(PersonNotFoundException::new), on);
161	        refuseCorrection(sheetId, claim.getPersonId(), amount, corrects, claim.getId());
162	        refuseRefUsed(sheetId, ref, claim.getId());
163	        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
164	            throw new ClaimLineException("A claim with lines takes its amount from its lines.");
165	        }
166	        Rollup.Snapshot before = rollup.take(sheetId);
167	        claim.setAmount(amount.setScale(2));
168	        claim.setDate(on);
169	        claim.setNote(note);
170	        claim.setCorrects(corrects);
171	        claim.setRef(ref);
172	        claim.setTags(tags);
173	        claim.setLockedBy(null);
174	        claim.setEditedBy(user);
175	        Claim updated = claims.saveAndFlush(claim);
176	        Person person = people.findByIdAndSheetId(updated.getPersonId(), sheetId)
177	                .orElseThrow(PersonNotFoundException::new);
178	        audit("CLAIM_EDITED", updated, person, user);
179	        recordTags(sheetId, tags);
180	        rollup.recordChanges(sheetId, user, before);
181	        return updated;
182	    }
