247	    /** Change a claim's status; a settle whose four-eyes and proof rules were already judged on another claim
248	     *  (a part-settle's original) skips them; a settle as of a date freezes the due as of it. */
249	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String voidReason,
250	            boolean judged, LocalDate on) {
251	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
252	        refuseClosed(sheetId, claim.getDueBy());
253	        roles.require(sheetId, user, switch (to) {
254	            case OPEN -> "open";
255	            case SETTLED, PENDING -> "settle";
256	            case VOID -> "void";
257	            case DRAFT, DELETED, REVIEW -> throw new IllegalStateException();
258	        });
259	        if (!claim.getStatus().canBecome(to)) {
260	            throw new ClaimStatusException(claim.getStatus(), to);
261	        }
262	        BigDecimal dueThen = to == ClaimStatus.SETTLED && on != null ? dueAsOf(sheetId, claim, on) : null;
263	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
264	            refuseVoidSettled(claim, sheetId, user);
265	        }
266	        if (to == ClaimStatus.VOID) {
267	            refuseVoidReason(sheetId, voidReason);
268	        }
269	        String reversed = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED
270	                ? " reversed=" + show(claim.getSettledDue()) : "";
271	        if (to == ClaimStatus.VOID && !voidReason.isEmpty()) {
272	            reversed += " reason=" + voidReason;
273	        }
274	        if (to == ClaimStatus.SETTLED && !judged) {
275	            refuseSettler(claim, user);
276	        }
277	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
278	            throw new ClaimDeferException("The claim is deferred until " + claim.getDeferredUntil() + ".");
279	        }
280	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
281	                .orElseThrow(PersonNotFoundException::new);
282	        if (to == ClaimStatus.OPEN) {
283	            refuseFlagged(sheetId, user, person);
284	            refuseNoteless(claim, shownDue(claim, person));
285	            refuseOverCap(claim);
286	        }
287	        Rollup.Snapshot before = rollup.take(sheetId);
288	        String number = claim.getNumber();
289	        if (to == ClaimStatus.OPEN && overReviewThreshold(claim, shownDue(claim, person))) {
290	            to = ClaimStatus.REVIEW;
291	            claim.setOpenedBy(user);
292	        } else if (to == ClaimStatus.OPEN) {
293	            number = sheets.nextClaimNumber(sheetId, claim.getDueBy());
294	            claim.setOpenedBy(user);
295	        }
296	        if (to == ClaimStatus.SETTLED) {
297	            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
298	            BigDecimal due = on != null ? dueThen : figure == null ? null : charged(claim, person, figure);
299	            if (!judged) {
300	                refuseUnproved(claim, person, due);
301	            }
302	            if (overLimit(sheetId, user, person, due)) {
303	                to = ClaimStatus.PENDING;
304	            } else {
305	                claim.setSettledDue(due);
306	            }
307	        }
308	        claim.setStatus(to);
309	        claim.setNumber(number);
310	        if (to == ClaimStatus.VOID) {
311	            claim.setVoidReason(voidReason.isEmpty() ? null : voidReason);
312	        }
313	        logStatus(claim, person, user);
314	        Claim updated = claims.saveAndFlush(claim);
315	        String event = switch (to) {
316	            case OPEN -> "CLAIM_OPENED";
317	            case REVIEW -> "CLAIM_REVIEW";
318	            case PENDING -> "CLAIM_PENDING";
319	            case SETTLED -> "CLAIM_SETTLED";
320	            case VOID -> "CLAIM_VOIDED";
321	            case DRAFT, DELETED -> throw new IllegalStateException();
322	        };
323	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED
324	                ? dueField(updated) + (on != null ? " on=" + on : "") : reversed);
325	        if (to == ClaimStatus.SETTLED) {
326	            notifyWatchers(updated, person, user);
327	        }
328	        rollup.recordChanges(sheetId, user, before);
329	        return updated;
330	    }
