332	    /** A claim's due as it stood at the end of a date, that date standing in for the sheet's today, as the as-of
333	     *  view works it out: its settled due then, else the figure its statement bound then, else its amount at the
334	     *  rate in force on its date of its person's grade then, late charge and floor on top (none when no rate
335	     *  applies). Refused for a date after the sheet's today, and a claim not on the sheet then. */
336	    private BigDecimal dueAsOf(String sheetId, Claim claim, LocalDate on) {
337	        LocalDate today = sheets.today(sheetId);
338	        if (on.isAfter(today)) {
339	            throw new ClaimSettleDateException("A claim cannot be settled as of a date after the sheet's today ("
340	                    + today + ").");
341	        }
342	        Claim then = history.findAsOf(Claim.class, sheetId, claim.getId(), on)
343	                .orElseThrow(() -> new ClaimSettleDateException("The claim was not on the sheet on " + on + "."));
344	        Person personThen = history.findAsOf(Person.class, sheetId, then.getPersonId(), on)
345	                .orElseThrow(() -> new ClaimSettleDateException("The claim was not on the sheet on " + on + "."));
346	        Sheet sheetOn = history.findAsOf(Sheet.class, sheetId, sheetId, on).orElseGet(() -> {
347	            // no change to the sheet counts by then: it stands as it was started
348	            Sheet now = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
349	            return new Sheet(sheetId, now.getCreatedBy(), now.getCreatedAt(), on);
350	        });
351	        sheetOn.setToday(on);
352	        Optional<Sheet> sheetThen = Optional.of(sheetOn);
353	        List<Rate> ratesThen = new ArrayList<>(history.listAsOf(Rate.class, sheetId, on));
354	        sheetRows.ancestors(sheetId).forEach(a -> ratesThen.addAll(history.listAsOf(Rate.class, a, on)));
355	        List<Claim> claimsThen = history.listAsOf(Claim.class, sheetId, on);
356	        BigDecimal figure = then.getSettledDue() != null ? then.getSettledDue()
357	                : then.isBound() ? then.getStatedDue()
358	                : Rollup.inForce(ratesThen, personThen.gradeOn(then.getDate()), then.getDate(), then)
359	                        .map(rate -> Rollup.rated(sheetThen, then, claimsThen, rate)).orElse(null);
360	        return figure == null ? null : Rollup.charged(sheetThen, then, personThen, figure);
361	    }
