363	    /** Delete a DRAFT claim: it becomes DELETED, counting nowhere, and cannot be edited, opened or voided
364	     *  until restored. Refused for a claim in any other status, a claim in a closed period, and a claim
365	     *  another user's editor is open on. */
366	    @Transactional
367	    public Claim delete(String sheetId, String user, long claimId) {
368	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
369	        refuseClosed(sheetId, claim.getDueBy());
370	        if (claim.getStatus() != ClaimStatus.DRAFT) {
371	            throw new ClaimDeleteException("Only a DRAFT claim can be deleted; this one is " + claim.getStatus() + ".");
372	        }
373	        refuseLocked(claim, user);
374	        return moveDeleted(sheetId, user, claim, ClaimStatus.DELETED, "CLAIM_DELETED");
