377	    /** Restore a DELETED claim to a DRAFT. Refused for a claim that is not DELETED, a claim deleted before the
378	     *  sheet's today, and a claim in a closed period. */
379	    @Transactional
380	    public Claim restore(String sheetId, String user, long claimId) {
381	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
382	        refuseClosed(sheetId, claim.getDueBy());
383	        if (claim.getStatus() != ClaimStatus.DELETED) {
384	            throw new ClaimDeleteException("Only a DELETED claim can be restored; this one is " + claim.getStatus() + ".");
385	        }
386	        LocalDate deletedOn = claim.getStatusLog().stream()
387	                .filter(line -> line.getStatus() == ClaimStatus.DELETED)
388	                .map(StatusChange::getOn)
389	                .reduce((first, last) -> last)
390	                .orElse(null);
391	        if (deletedOn == null || !deletedOn.equals(sheets.today(sheetId))) {
392	            throw new ClaimDeleteException("A deleted claim can only be restored on the day it was deleted.");
393	        }
394	        return moveDeleted(sheetId, user, claim, ClaimStatus.DRAFT, "CLAIM_RESTORED");
395	    }
