411	    /** Review a REVIEW claim: it becomes OPEN, numbered now, keeping who opened it; writes CLAIM_REVIEWED
412	     *  then CLAIM_OPENED. Refused unless the claim is REVIEW and the user is a steward. */
413	    @Transactional
414	    public Claim review(String sheetId, String user, long claimId) {
415	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
416	        refuseClosed(sheetId, claim.getDueBy());
417	        if (claim.getStatus() != ClaimStatus.REVIEW) {
418	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.OPEN);
419	        }
