426	        audit("CLAIM_REVIEWED", claim, person, user);
427	        String number = sheets.nextClaimNumber(sheetId, claim.getDueBy());
428	        claim.setNumber(number);
429	        claim.setStatus(ClaimStatus.OPEN);
