437	    /** Approve a PENDING claim: it becomes SETTLED, its due fixed at the figure its person's last statement bound
438	     *  it to, else its live figure now, its late charge on
439	     *  the sheet's today frozen in on top (with no figure then, its due stays live). Refused unless the
440	     *  claim is PENDING and the user is a steward other than the one who opened it or last edited it. */
441	    @Transactional
442	    public Claim approve(String sheetId, String user, long claimId) {
443	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
444	        refuseClosed(sheetId, claim.getDueBy());
445	        if (claim.getStatus() != ClaimStatus.PENDING) {
446	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
447	        }
448	        if (!mayApprove(sheetId, user, claim)) {
449	            throw new ClaimApprovalException("Only a steward or the person's approver can approve a claim.");
450	        }
451	        if (user.equals(claim.getOpenedBy())) {
452	            throw new ClaimApprovalException("The user who opened a claim cannot approve it.");
453	        }
454	        if (user.equals(claim.getEditedBy())) {
455	            throw new ClaimApprovalException("The user who last edited a claim cannot approve it.");
456	        }
457	        Rollup.Snapshot before = rollup.take(sheetId);
458	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
459	                .orElseThrow(PersonNotFoundException::new);
460	        BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
461	        BigDecimal due = figure == null ? null : charged(claim, person, figure);
462	        refuseUnproved(claim, person, due);
463	        claim.setSettledDue(due);
464	        claim.setStatus(ClaimStatus.SETTLED);
465	        logStatus(claim, person, user);
466	        Claim updated = claims.saveAndFlush(claim);
467	        audit("CLAIM_APPROVED", updated, person, user, updated.getNumber(), dueField(updated));
468	        notifyWatchers(updated, person, user);
469	        rollup.recordChanges(sheetId, user, before);
470	        return updated;
471	    }
