492	    /** Remind an OPEN or PENDING claim: write REMIND and mark it reminded on the sheet's today. When its
493	     *  previous reminder was at least the sheet's escalation gap before today, and it was never escalated,
494	     *  also escalate it: write ESCALATE after REMIND. Refused for a claim in any other status, and a claim
495	     *  already reminded on the sheet's today. */
496	    @Transactional
497	    public Claim remind(String sheetId, String user, long claimId) {
498	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
499	        if (!claim.getStatus().isOpen()) {
500	            throw new ClaimRemindException("Only an OPEN or PENDING claim can be reminded.");
501	        }
502	        LocalDate today = sheets.today(sheetId);
503	        if (today.equals(claim.getRemindedOn())) {
504	            throw new ClaimRemindException("The claim was already reminded today.");
505	        }
506	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
507	                .orElseThrow(PersonNotFoundException::new);
508	        Integer gap = sheetRows.findById(sheetId).map(Sheet::getEscalateAfter).orElse(null);
509	        LocalDate previous = claim.getRemindedOn();
510	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
511	                && !previous.plusDays(gap).isAfter(today);
512	        claim.setRemindedOn(today);
513	        if (escalate) {
514	            claim.setEscalated(true);
515	        }
516	        Claim updated = claims.saveAndFlush(claim);
517	        audit("REMIND", updated, person, user);
518	        if (escalate) {
519	            audit("ESCALATE", updated, person, user);
520	        }
521	        return updated;
522	    }
