584	    /** Add a line to a DRAFT claim: its amount becomes what its lines add up to, the user counts as having
585	     *  edited it, and CLAIM_LINE_ADDED is written. Refused for an empty label, a quantity below 1, a unit
586	     *  amount below 0.00 or of more than two decimals, a claim that is not a DRAFT, a claim in a closed period,
587	     *  and a claim another user has locked. */
588	    @Transactional
589	    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
590	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
591	        if (label.isEmpty()) {
592	            throw new ClaimLineException("Enter a label for the line.");
593	        }
594	        if (qty < 1) {
595	            throw new ClaimLineException("A line's quantity is a whole number of at least 1.");
596	        }
597	        if (unit.signum() < 0 || unit.stripTrailingZeros().scale() > 2) {
598	            throw new ClaimLineException("A line's unit amount is 0.00 or more, with two decimals.");
599	        }
600	        if (claim.getStatus() != ClaimStatus.DRAFT) {
601	            throw new ClaimNotDraftException(claim.getStatus());
602	        }
603	        refuseClosed(sheetId, claim.getDueBy());
604	        refuseLocked(claim, user);
605	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
606	                .orElseThrow(PersonNotFoundException::new);
607	        Rollup.Snapshot before = rollup.take(sheetId);
608	        BigDecimal shown = unit.setScale(2);
609	        claim.addLine(label, qty, shown);
610	        claim.setEditedBy(user);
611	        Claim updated = claims.saveAndFlush(claim);
612	        // A change to its lines alone may not reach the entity listener: keep its state for the as-of view.
613	        history.saved(updated);
614	        audit("CLAIM_LINE_ADDED", updated, person, user, updated.getNumber(),
615	                " label=" + label + " qty=" + qty + " unit=" + shown.toPlainString());
616	        rollup.recordChanges(sheetId, user, before);
617	        return updated;
618	    }
