620	    /** Re-settle a SETTLED claim: freeze it again at the figure it would have today as an OPEN claim bound by
621	     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
622	     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
623	    @Transactional
624	    public Claim resettle(String sheetId, String user, long claimId) {
625	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
626	        refuseClosed(sheetId, claim.getDueBy());
627	        if (!roles.isSteward(sheetId, user)) {
628	            throw new ClaimResettleException("Only a steward can re-settle a claim.");
629	        }
630	        if (claim.getStatus() != ClaimStatus.SETTLED) {
631	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
632	        }
633	        Rollup.Snapshot before = rollup.take(sheetId);
634	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
635	                .orElseThrow(PersonNotFoundException::new);
636	        BigDecimal old = claim.getSettledDue();
637	        BigDecimal figure = liveDue(claim, person);
638	        BigDecimal due = null;
639	        if (figure != null) {
640	            Sheet sheet = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
641	            LocalDate lateFrom = sheet.lateFrom(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
642	            BigDecimal floored = sheet.floored(figure, claim.getDate());
643	            due = claim.isCorrection() ? figure
644	                    : claim.isWaived() ? floored
645	                    : floored.add(sheet.lateCharge(floored, lateFrom, claim.getDate()));
646	        }
647	        claim.setSettledDue(due);
648	        logStatus(claim, person, user);
649	        Claim updated = claims.saveAndFlush(claim);
650	        audit("CLAIM_RESETTLED", updated, person, user, updated.getNumber(),
651	                " old=" + show(old) + " new=" + show(due));
652	        notifyWatchers(updated, person, user);
653	        rollup.recordChanges(sheetId, user, before);
654	        return updated;
655	    }
