745	    /** Move a claim as a reassign does; one already the person's is refused only when {@code refuseOwn}. */
746	    private Claim move(String sheetId, String user, long claimId, long toPersonId, boolean refuseOwn) {
747	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
748	        refuseClosed(sheetId, claim.getDueBy());
749	        if (!roles.allows(sheetId, user, "reassign")) {
750	            throw new ClaimReassignException("Your role may not reassign a claim.");
751	        }
752	        if (!claim.getStatus().canMove()) {
753	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
754	        }
755	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
756	                .orElseThrow(PersonNotFoundException::new);
757	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
758	        if (refuseOwn && from.getId().equals(to.getId())) {
759	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
760	        }
761	        refuseRetired(to, claim.getDate());
762	        Rollup.Snapshot before = rollup.take(sheetId);
763	        claim.setPersonId(to.getId());
764	        claim.setStated(false, null);
765	        if (claim.getNumber() != null) {
766	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
767	        }
768	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
769	        Claim updated = claims.saveAndFlush(claim);
770	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
771	                " from=" + from.getName() + " to=" + to.getName());
772	        rollup.recordChanges(sheetId, user, before);
773	        return updated;
774	    }
