780	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any figure a
781	     *  statement bound it to; a new OPEN claim of the person with the amount split off, the same date and
782	     *  note, the next number, opened by the user and due by the terms-th business day after its date (by the terms in
783	     *  force on it and the sheet's holidays), is
784	     *  listed as the sheet's newest, naming the original's number as split from. Refused unless the user's
785	     *  role may open a claim, the claim is OPEN and not deferred, and the amount is above 0.00 and below the
786	     *  claim's; and for a claim in a closed period. */
787	    @Transactional
788	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
789	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
790	        refuseClosed(sheetId, claim.getDueBy());
791	        roles.require(sheetId, user, "open");
792	        if (claim.getStatus() != ClaimStatus.OPEN) {
793	            throw new ClaimSplitException("Only an OPEN claim can be split.");
794	        }
795	        LocalDate today = sheets.today(sheetId);
796	        if (claim.deferredOn(today)) {
797	            throw new ClaimSplitException("The claim is deferred until " + claim.getDeferredUntil() + ".");
798	        }
799	        BigDecimal part = amount.setScale(2);
800	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
801	            throw new ClaimSplitException("Split off more than 0.00 and less than the claim's amount.");
802	        }
803	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
804	                .orElseThrow(PersonNotFoundException::new);
805	        Rollup.Snapshot before = rollup.take(sheetId);
806	        claim.setAmount(claim.getAmount().subtract(part));
807	        claim.setStated(false, null);
808	        Claim kept = claims.saveAndFlush(claim);
809	        int terms = termsOn(sheetId, person, today);
810	        Claim split = new Claim(sheetId, person.getId(), part, claim.getDate(),
811	                holidays.businessDaysAfter(sheetId, claim.getDate(), terms),
812	                claim.getNote(), null);
813	        split.setTerms(terms);
814	        split.setListOrder(claims.maxListOrder(sheetId) + 1);
815	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
816	        split.setStatus(ClaimStatus.OPEN);
817	        split.setNumber(sheets.nextClaimNumber(sheetId, split.getDueBy()));
818	        split.setOpenedBy(user);
819	        split.setSplitFrom(claim.getNumber());
820	        split.setTags(claim.getTags());
821	        logStatus(split, person, user);
822	        split = claims.saveAndFlush(split);
823	        audit("CLAIM_SPLIT", kept, person, user, kept.getNumber(), " into=" + split.getNumber());
824	        audit("CLAIM_OPENED", split, person, user);
825	        rollup.recordChanges(sheetId, user, before);
826	        return new Split(kept, split);
827	    }
