829	    /** Part-settle an OPEN claim: split the amount off it as a split does, then settle the new claim as a settle
830	     *  by the user does (PENDING when over the clerk limit). The four-eyes rules and the proof rule are judged
831	     *  on the original claim, at its figure before the split; the new claim, opened by the user, is not held
832	     *  to them. Refused whole when the split or the settle would be. */
833	    @Transactional
834	    public Split settlePart(String sheetId, String user, long claimId, BigDecimal amount) {
835	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
836	        refuseClosed(sheetId, claim.getDueBy());
837	        roles.require(sheetId, user, "settle");
838	        if (claim.getStatus() == ClaimStatus.OPEN) {
839	            refuseSettler(claim, user);
840	            Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
841	                    .orElseThrow(PersonNotFoundException::new);
842	            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
843	            refuseUnproved(claim, person, figure == null ? null : charged(claim, person, figure));
844	        }
845	        Split done = split(sheetId, user, claimId, amount);
846	        Claim settled = changeStatus(sheetId, user, done.split().getId(), ClaimStatus.SETTLED, "", true);
847	        return new Split(done.kept(), settled);
848	    }
