854	    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
855	     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
856	     *  refused, as is one not on the sheet. */
857	    @Transactional
858	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
859	        Set<Long> chosen = new HashSet<>(claimIds);
860	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
861	            return new BulkOpened(0, chosen.size(), List.of());
862	        }
863	        List<Claim> opened = new ArrayList<>();
864	        for (Claim claim : inListOrder(sheetId, chosen)) {
865	            try {
866	                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
867	            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException
868	                    | ActionNotAllowedException | ClaimNoteException | ClaimCapException | ClaimFlaggedException e) {
869	                // refused: left as it is
870	            }
871	        }
872	        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
873	    }
