875	    /** What a bulk settle did: how many it settled (PENDING included) and refused, the claims it changed, and
876	     *  the number of the batch it made (none when it settled none). */
877	    public record BulkSettled(int settled, int refused, List<Claim> claims, Integer batch) {
878	    }
