880	    /** Settle the chosen claims together in list order (people by their position, each person's
881	     *  claims newest first), each as a single settle by the user would; one a clerk puts PENDING counts as
882	     *  settled. All or nothing: if any one cannot be settled (or is not on the sheet), none is, every one
883	     *  counts as refused and nothing is written. Otherwise they are the sheet's next batch, each claim taking
884	     *  its number, and BATCH_SETTLED follows the claims' own lines with the frozen figures of those SETTLED
885	     *  added up. */
886	    @Transactional
887	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> claimIds) {
888	        Set<Long> chosen = new HashSet<>(claimIds);
889	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
890	            return new BulkSettled(0, chosen.size(), List.of(), null);
891	        }
892	        List<Claim> found = inListOrder(sheetId, chosen);
893	        if (found.size() != chosen.size()) {
894	            return new BulkSettled(0, chosen.size(), List.of(), null);
895	        }
896	        List<Claim> settled = new ArrayList<>();
897	        for (Claim claim : found) {
898	            try {
899	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
900	            } catch (ClaimStatusException | ClaimSettlerException | ClaimDeferException | ClaimProofException
901	                    | PeriodClosedException | ActionNotAllowedException
902	                    | ClaimNotFoundException e) {
903	                // refused: undo every settle made so far, and write none of their lines
904	                TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
905	                return new BulkSettled(0, chosen.size(), List.of(), null);
906	            }
907	        }
908	        Integer batch = null;
909	        if (!settled.isEmpty()) {
910	            batch = sheets.nextSettleBatch(sheetId);
911	            BigDecimal total = BigDecimal.ZERO.setScale(2);
912	            for (Claim claim : settled) {
913	                claim.setSettleBatch(batch);
914	                if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
915	                    total = total.add(claim.getSettledDue());
916	                }
917	            }
918	            settled = claims.saveAllAndFlush(settled);
919	            audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
920	                    + " count=" + settled.size() + " total=" + total.toPlainString());
921	        }
922	        return new BulkSettled(settled.size(), 0, settled, batch);
923	    }
