45	    /** A claim as the screen shows it: the amount with two decimals, the date YYYY-MM-DD, no number unless opened,
46	     *  the due fixed when it was settled (none while its due is live)
47	     *  who opened it (none while a draft), whether its person's last statement bound it and the figure
48	     *  it bound (none while unbound, or when that was n/a), and the number a correction corrects (none
49	     *  otherwise), its status log, oldest first, and the date it is deferred until (none when never deferred), its proofs count and how many of them are receipts and photos,
50	     *  the user whose editor is open on it (none while unlocked), and whether it was added while its period
51	     *  was soft-closed, and the last day it was reminded (none when never), and its external reference (none when
52	     *  not given), and its tags, sorted, and its comments, in the order written, and its lines, in the order added, and whether its late charge is waived, and whether it is held. */
53	    public record ClaimView(long id, long personId, String amount, String date, String note,
54	            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
55	            String statedDue, String corrects, String dueBy, List<StatusLine> statusLog, String deferredUntil,
56	            int proofs, int proofReceipts, int proofPhotos, String splitFrom, String lockedBy, boolean lateEntry,
57	            String remindedOn, String ref, List<String> tags, String voidReason,
58	            List<CommentLine> comments, Integer settleBatch, List<LineView> lines, boolean waived, boolean held) {
59	
60	        public static ClaimView of(Claim claim) {
61	            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
62	                    claim.getDate().toString(), claim.getNote(), claim.getStatus(), claim.getNumber(),
63	                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
64	                    claim.getOpenedBy(), claim.isStated(),
65	                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
66	                    claim.getCorrects(), claim.getDueBy().toString(),
67	                    claim.getStatusLog().stream().map(StatusLine::of).toList(),
68	                    claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(),
69	                    claim.getProofs(), claim.getProofs(ProofKind.RECEIPT), claim.getProofs(ProofKind.PHOTO),
70	                    claim.getSplitFrom(), claim.getLockedBy(),
71	                    claim.isLateEntry(),
72	                    claim.getRemindedOn() == null ? null : claim.getRemindedOn().toString(), claim.getRef(),
73	                    claim.getTags(), claim.getVoidReason(),
74	                    claim.getComments().stream().map(CommentLine::of).toList(), claim.getSettleBatch(),
75	                    claim.getLines().stream().map(LineView::of).toList(), claim.isWaived(), claim.isHeld());
76	        }
77	    }
