105	    /** A claim's fields; a missing date takes the sheet's today, a missing note is empty. A negative
106	     *  amount (a correction) names the number of the claim it corrects. */
107	    public record ClaimRequest(
108	            @NotNull @Digits(integer = 13, fraction = 2) BigDecimal amount,
109	            LocalDate date,
110	            @Size(max = 1000) String note,
111	            @Size(max = 220) String corrects,
112	            @Size(max = 200) String ref,
113	            @Size(max = 2000) String tags) {
114	
115	        String noteOrEmpty() {
116	            return note == null ? "" : note.trim();
117	        }
118	
119	        /** The external reference, trimmed; none when blank. */
120	        String refOrNone() {
121	            return ref == null || ref.isBlank() ? null : ref.trim();
122	        }
123	
124	        /** The tags, comma separated: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
125	        List<String> tagList() {
126	            return tags == null ? List.of()
127	                    : Arrays.stream(tags.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT))
128	                            .filter(t -> !t.isEmpty()).distinct().sorted().toList();
129	        }
130	
131	        /** The number a correction names, trimmed; none when blank. */
132	        String correctsOrNone() {
133	            return corrects == null || corrects.isBlank() ? null : corrects.trim();
134	        }
135	    }
