     1	package net.officefloor.hq.app.claim;
     2	
     3	import java.util.Set;
     4	
     5	/** A claim's status: DRAFT when added; it is opened, then settled. A claim whose due is above the review
     6	 *  threshold goes to REVIEW when opened instead, until a steward reviews it (OPEN); it can be voided. A clerk settling a due above the clerk
     7	 *  limit puts it PENDING instead, until a steward approves it (SETTLED) or rejects it (back to OPEN). A
     8	 *  DRAFT, OPEN or PENDING claim can be voided, and a SETTLED one by a steward within 7 days of settling. A
     9	 *  DRAFT can be deleted (DELETED, counting nowhere), and restored to DRAFT on the sheet's today it was deleted. */
    10	public enum ClaimStatus {
    11	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
    12	
    13	    /** Whether a claim in this status can move to the given one by opening, settling or voiding it;
    14	     *  approving and rejecting move a PENDING claim on, and deleting and restoring a DRAFT. */
    15	    public boolean canBecome(ClaimStatus to) {
    16	        return switch (this) {
    17	            case DRAFT -> Set.of(OPEN, VOID).contains(to);
    18	            case OPEN -> Set.of(SETTLED, VOID).contains(to);
    19	            case PENDING, REVIEW -> to == VOID;
    20	            case SETTLED -> to == VOID;
    21	            case VOID, DELETED -> false;
    22	        };
    23	    }
    24	
    25	    /** Whether a claim in this status can be reassigned to another person: DRAFT, OPEN or PENDING. */
    26	    public boolean canMove() {
    27	        return this == DRAFT || this == OPEN || this == PENDING;
    28	    }
    29	
    30	    /** Whether a claim in this status counts toward claimed, due-total and statements. */
    31	    public boolean counts() {
    32	        return this == OPEN || this == PENDING || this == SETTLED;
    33	    }
    34	
    35	    /** Whether a claim in this status is still open: OPEN or PENDING. It goes overdue and bears the late
    36	     *  charge, and a hold on its person takes it out of the live totals. */
    37	    public boolean isOpen() {
    38	        return this == OPEN || this == PENDING;
    39	    }
    40	}
