    62	    @Transactional
    63	    public List<Claim> paste(String sheetId, String user, String text) {
    64	        List<Line> lines = new ArrayList<>();
    65	        Set<String> refs = new HashSet<>();
    66	        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
    67	        for (int i = 0; i < raw.length; i++) {
    68	            if (!raw[i].isBlank()) {
    69	                Line line = parse(sheetId, i + 1, raw[i]);
    70	                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
