    76	        if (lines.isEmpty()) {
    77	            throw new ClaimPasteException("Paste at least one line of name,amount,date,note.");
    78	        }
    79	        List<Claim> before = claimsRepo.findBySheetIdOrderByListOrderDesc(sheetId);
