1077	        sheetThen.setToday(asOf);
1078	        Optional<Sheet> onDate = Optional.of(sheetThen);
1079	        List<Rate> ratesThen = new ArrayList<>(history.listAsOf(Rate.class, sheetId, asOf));
1080	        sheetRows.ancestors(sheetId).forEach(a -> ratesThen.addAll(history.listAsOf(Rate.class, a, asOf)));
1081	        List<Claim> claimsThen = history.listAsOf(Claim.class, sheetId, asOf).stream()
1082	                .filter(c -> c.getPersonId().equals(personId)).toList();
1083	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
1084	        Rollup.Snapshot before = rollup.take(sheetId);
1085	        Map<Long, BigDecimal> figures = new HashMap<>();
1086	        BigDecimal total = BigDecimal.ZERO.setScale(2);
1087	        boolean figure = false;
1088	        for (Claim claim : claimsThen) {
1089	            if (!claim.getStatus().counts() || Rollup.heldOut(claim, then, asOf) || claim.deferredOn(asOf)) {
1090	                continue;
1091	            }
1092	            BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
1093	                    : claim.isBound() ? claim.getStatedDue()
1094	                    : Rollup.inForce(ratesThen, then.gradeOn(claim.getDate()), claim.getDate(), claim)
1095	                            .map(rate -> Rollup.rated(onDate, claim, claimsThen, rate)).orElse(null);
1096	            if (due != null) {
1097	                due = Rollup.charged(onDate, claim, then, due);
1098	                total = total.add(due);
1099	                figure = true;
1100	            }
1101	            figures.put(claim.getId(), due);
1102	        }
1103	        for (Claim claim : theirs) {
1104	            claim.setStated(figures.containsKey(claim.getId()), figures.get(claim.getId()));
1105	        }
1106	        boolean rated = Rollup.inForce(ratesThen, then.gradeOn(asOf), asOf).isPresent();
1107	        BigDecimal dueTotal = rated || figure ? sheetThen.capped(total) : null;
1108	        int counted = figures.size();
1109	        claims.saveAllAndFlush(theirs);
1110	        statements.saveAndFlush(new Statement(sheetId, personId, asOf, dueTotal, counted));
1111	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
1112	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted
1113	                + " asof=" + asOf);
