13	/** People's figures added up, leaving out the single highest and the single lowest when there are
14	 *  three or more. */
15	function trimmed(figures: bigint[]): bigint {
16	  const sum = figures.reduce((s, f) => s + f, 0n);
17	  if (figures.length < 3) return sum;
18	  const max = figures.reduce((m, f) => (f > m ? f : m));
19	  const min = figures.reduce((m, f) => (f < m ? f : m));
20	  return sum - max - min;
21	}
