23	// The due figures the screen shows, worked out in one place so the people list, the periods list,
24	// the summary and the header always agree.
25	@Injectable({ providedIn: 'root' })
26	export class Figures {
27	  private readonly claims = inject(Claims);
28	  private readonly crews = inject(Crews);
29	  private readonly people = inject(People);
30	  private readonly periods = inject(Periods);
31	  private readonly rates = inject(Rates);
32	  private readonly roles = inject(Roles);
33	  private readonly session = inject(Session);
34	
35	  /** A person's due-total: the sum of their figures, at most the sheet's cap. Null (n/a) is not capped. */
36	  dueCents(p: Person): bigint | null {
37	    const sum = this.sumCents(p);
38	    const cap = this.capCents();
39	    return sum !== null && cap !== null && sum > cap ? cap : sum;
40	  }
41	
42	  /** How far the sum of a person's figures is above the sheet's cap; 0 when it is not (or is n/a). */
43	  excessCents(p: Person): bigint {
44	    const sum = this.sumCents(p);
45	    const cap = this.capCents();
46	    return sum !== null && cap !== null && sum > cap ? sum - cap : 0n;
47	  }
48	
49	  private capCents(): bigint | null {
50	    const cap = this.session.cap();
51	    return cap === null ? null : hundredths(cap);
52	  }
53	
54	  /** The sum of the figures of a person's claims that count live (not left out by a hold): a settled claim's frozen due, else the
55	   *  figure their last statement bound it to, else its live due at the rate in force on its date (a
56	   *  claim with no figure adds nothing). Null when the grade in force on the sheet's today has no rate
57	   *  there and no claim has a figure. */
58	  sumCents(p: Person): bigint | null {
59	    let sum = 0n;
60	    let keptFigure = false;
61	    for (const c of this.claims.live().filter((c) => c.personId === p.id)) {
62	      if (c.settledDue !== null || (bound(c) && c.statedDue !== null)) keptFigure = true;
63	      // a claim priced at the grade in force on its date keeps a figure too
64	      else if (!bound(c) && this.rates.inForceFor(gradeOn(p.grades, c.date), c.date, c.id) !== undefined) keptFigure = true;
65	      sum += this.figureCents(c, p);
66	    }
67	    const today = this.session.today();
68	    const rated = today ? this.rates.inForce(gradeOn(p.grades, today), today) !== undefined : false;
69	    return rated || keptFigure ? sum : null;
70	  }
