72	  /** The due of a person's SETTLED claims that count live, at their frozen figures, corrections included. */
73	  settledCents(p: Person): bigint {
74	    return this.claims
75	      .live()
76	      .filter((c) => c.personId === p.id && c.status === 'SETTLED')
77	      .reduce((sum, c) => sum + this.figureCents(c, p), 0n);
78	  }
79	
80	  /** The due of a person's OPEN and PENDING claims that count live (not deferred or retired-and-excluded). */
81	  openCents(p: Person): bigint {
82	    return this.claims
83	      .live()
