269	  /** What a candidate rate (a percent with up to two decimals) would change if it applied to a grade on
270	   *  every date: of the OPEN and PENDING claims of people on that grade on the claim's date, not bound
271	   *  by a statement, how many would show a different due, and the sum of new due minus current due in
272	   *  cents (a due shown as n/a counting as nothing). Nothing is saved. */
273	  ratePreview(grade: string, pct: string): { count: number; diffCents: bigint } {
274	    const people = new Map(this.people.people().map((p) => [p.id, p]));
275	    const rate = hundredths(pct);
276	    let count = 0;
277	    let diffCents = 0n;
278	    for (const c of this.claims.claims()) {
279	      const p = people.get(c.personId);
280	      if (!p || !isOpen(c) || bound(c) || gradeOn(p.grades, c.date) !== grade) continue;
281	      const roundOn = this.claims.roundingDate(c);
282	      const now = this.rates.dueCents(hundredths(c.amount), grade, c.date, roundOn, c.id);
283	      const was = now === null ? null : this.claims.chargedCents(c, now);
284	      const will = this.claims.chargedCents(c, rounded(hundredths(c.amount) * rate, 10000n, this.session.roundsHalfUp(roundOn)));
285	      if (was === will) continue;
286	      count++;
287	      diffCents += will - (was ?? 0n);
288	    }
289	    return { count, diffCents };
290	  }
