332	  /** Each period's due-total for each person, in cents, by period id then person id, counting the claims
333	   *  whose due-by falls in it that pass `counts`, each its due as shown now. */
334	  private personPeriodCents(counts: (c: Claim, period: Period) => boolean): Map<number, Map<number, bigint>> {
335	    const grades = new Map(this.people.people().map((p) => [p.id, p.grades]));
336	    const sums = new Map<number, Map<number, bigint>>();
337	    for (const c of this.claims.periodCandidates()) {
338	      const period = this.periods.of(c.dueBy);
339	      if (!period || !counts(c, period)) continue;
340	      const byPerson = sums.get(period.id) ?? new Map<number, bigint>();
341	      byPerson.set(c.personId, (byPerson.get(c.personId) ?? 0n) + this.periodClaimCents(c, grades));
342	      sums.set(period.id, byPerson);
343	    }
344	    return sums;
345	  }
