347	  /** A claim's due as the period figures count it: a settled claim's frozen due, else as its person's
348	   *  last statement bound it, else its live due, an overdue claim's late charge on top; 0 with no figure. */
349	  private periodClaimCents(c: Claim, grades: Map<number, Person['grades']>): bigint {
350	    let due: bigint | null;
351	    if (c.settledDue !== null) due = hundredths(c.settledDue);
352	    else if (bound(c)) due = c.statedDue === null ? null : hundredths(c.statedDue);
353	    else {
354	      const grade = grades.get(c.personId);
355	      due = grade === undefined ? null : this.rates.dueCents(hundredths(c.amount), gradeOn(grade, c.date), c.date, this.claims.roundingDate(c), c.id);
356	    }
357	    if (due !== null && c.settledDue === null) due = this.claims.chargedCents(c, due);
358	    return due ?? 0n;
359	  }
