361	  /** Each period's carried figure for each person, in cents, by period id then person id: the due of the
362	   *  person's claims that count (as the period figures count them) whose due-by falls in a period ending
363	   *  before this one starts, and that were still OPEN or PENDING at the end of this period's last day, as
364	   *  their status log records it; and their opening balance for it on top. */
365	  private readonly carriedCents = computed(() => {
366	    const grades = new Map(this.people.people().map((p) => [p.id, p.grades]));
367	    const periods = this.periods.periods();
368	    const sums = new Map<number, Map<number, bigint>>();
369	    for (const c of this.claims.periodCandidates()) {
370	      const own = this.periods.of(c.dueBy);
371	      if (!own) continue;
372	      for (const period of periods) {
373	        if (own.to >= period.from) continue;
374	        const status = statusAt(c, period.to);
375	        if (status !== 'OPEN' && status !== 'PENDING') continue;
376	        const byPerson = sums.get(period.id) ?? new Map<number, bigint>();
377	        byPerson.set(c.personId, (byPerson.get(c.personId) ?? 0n) + this.periodClaimCents(c, grades));
378	        sums.set(period.id, byPerson);
379	      }
380	    }
381	    for (const period of periods) {
382	      for (const [id, opening] of Object.entries(period.openings ?? {})) {
383	        const byPerson = sums.get(period.id) ?? new Map<number, bigint>();
384	        byPerson.set(Number(id), (byPerson.get(Number(id)) ?? 0n) + hundredths(opening));
385	        sums.set(period.id, byPerson);
386	      }
387	    }
388	    return sums;
389	  });
