1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Injectable, computed, inject, signal } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { People, Person, gradeOn, retiredBy } from './people';
5	import { hundredths, rounded } from './rates';
6	import { Session, addDays, daysBetween, isDate } from './session';
7	
8	/** The kinds a proof can be; one added with none chosen is a receipt. */
9	export const PROOF_KINDS = ['receipt', 'photo'] as const;
10	export type ProofKind = (typeof PROOF_KINDS)[number];
11	
12	export interface Claim {
13	  id: number;
14	  personId: number;
15	  /** Two decimals, as the server stores it. */
16	  amount: string;
17	  date: string;
18	  note: string;
19	  status: ClaimStatus;
20	  /** Given when opened: the next on the sheet in its fiscal year (FY2026-1, FY2026-2, ...), or while numbering by period the next in its
21	   *  period (<period name>-1, ...) or in no period (X-1, ...); null while a draft. */
22	  number: string | null;
23	  /** The due fixed when it was settled, two decimals; null while its due is live (not settled, or
24	   *  settled while its grade had no rate). */
25	  settledDue: string | null;
26	  /** The user who opened it; null while a draft. That user cannot settle it. */
27	  openedBy: string | null;
28	  /** Bound by its person's last statement, which counted it: it shows and totals `statedDue` (see `bound`). */
29	  stated: boolean;
30	  /** The figure the last statement bound, two decimals; null while unbound, or when that was n/a. */
31	  statedDue: string | null;
32	  /** The date it is due by (YYYY-MM-DD): fixed when it was added, its date plus the terms of its person's
33	   *  grade in force on its date then (the sheet's terms when the grade has none of its own). */
34	  dueBy: string;
35	  /** A correction's (a negative amount): the number of the SETTLED claim of the same person it
36	   *  corrects; null otherwise. */
37	  corrects: string | null;
38	  /** Its status log: one line per status it has had, oldest first. */
39	  statusLog: StatusLine[];
40	  /** The date it was deferred until (YYYY-MM-DD); null when never deferred. It is deferred only while
41	   *  OPEN and the sheet's today is before it (see `Claims.deferred`). */
42	  deferredUntil: string | null;
43	  /** How many proofs it has. One whose due is above the proof threshold in force on its date cannot be
44	   *  settled or approved with none. */
45	  proofs: number;
46	  /** How many of its proofs are receipts. */
47	  proofReceipts: number;
48	  /** How many of its proofs are photos. */
49	  proofPhotos: number;
50	  /** The number of the claim it was split from; null when it was not split off another. */
51	  splitFrom: string | null;
52	  /** The user whose editor is open on it, locking it for every other user until they save or cancel it,
53	   *  or the sheet's today changes; null while unlocked. */
54	  lockedBy: string | null;
55	  /** Whether it was added while its period was soft-closed. */
56	  lateEntry: boolean;
57	  /** The last day (YYYY-MM-DD) a reminder was written for it; null when never reminded. */
58	  remindedOn: string | null;
59	  /** Its external reference, unique on the sheet without regard to case; null when not given. */
60	  ref: string | null;
61	  /** Its tags: trimmed, lower-cased, without repeats, sorted; empty when it carries none. */
62	  tags: string[];
63	  /** The reason it was voided with, from the sheet's list; null when not voided, or voided without one. */
64	  voidReason: string | null;
65	  /** Its comments, in the order written. */
66	  comments: CommentLine[];
67	  /** The number of the bulk settle batch that settled it; null when settled one at a time, or never. */
68	  settleBatch: number | null;
69	  /** Its lines, in the order added; while it has any, its amount is what they add up to. */
70	  lines: ClaimLine[];
71	  /** Whether a steward waived its late charge: from then on it bears none, whatever its overdue state. */
72	  waived: boolean;
73	  /** Whether it is on hold: while OPEN or PENDING and bound by no statement, it counts in claimed but in no due figure. */
74	  held: boolean;
75	}
76	
77	/** A line of a claim: its label, a whole quantity of at least 1 and a unit amount, two decimals. */
78	export interface ClaimLine {
79	  label: string;
80	  qty: number;
81	  unit: string;
82	}
83	
84	/** A comment on a claim: who wrote it, the sheet's today then (YYYY-MM-DD), and its text. */
85	export interface CommentLine {
86	  by: string;
87	  on: string;
88	  text: string;
89	}
90	
91	/** A line of a claim's status log: the status it took, who changed it, the sheet's today then
92	 *  (YYYY-MM-DD), and the due it had then, two decimals (null when n/a). */
93	export interface StatusLine {
94	  status: ClaimStatus;
95	  by: string;
96	  on: string;
97	  due: string | null;
98	}
99	
100	/** DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT, OPEN or PENDING -> VOID. A clerk settling a
101	 *  due above the clerk limit makes it PENDING: a steward approves it (SETTLED) or rejects it (OPEN). A
102	 *  steward can re-settle a SETTLED claim at its figure today. A DRAFT can be deleted (DELETED, counting
103	 *  nowhere) and restored to DRAFT on the sheet's today it was deleted. A claim whose due is above the review
104	 *  threshold goes to REVIEW when opened (counting nowhere, unnumbered) until a steward reviews it (OPEN). */
105	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
106	
107	/** A status change a claim's buttons ask for. */
108	export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle' | 'delete' | 'restore' | 'review';
109	
110	/** Whether a claim in this status counts toward claimed, due-total and every total. */
111	export function counts(c: Claim): boolean {
112	  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
113	}
114	
115	/** Whether a claim in this status counts toward the totals; no status (not yet added) does not. */
116	export function countsAt(status: ClaimStatus | null): boolean {
117	  return status === 'OPEN' || status === 'PENDING' || status === 'SETTLED';
118	}
119	
120	/** The status a claim had at the end of a day (YYYY-MM-DD), as its status log records it: its latest line
121	 *  dated on or before it; null when it was added after it. A claim with no log has its status now. */
122	export function statusAt(c: Claim, day: string): ClaimStatus | null {
123	  if (c.statusLog.length === 0) return c.status;
124	  let status: ClaimStatus | null = null;
125	  for (const l of c.statusLog) if (l.on <= day) status = l.status;
126	  return status;
127	}
128	
129	/** Whether a claim is still open (OPEN or PENDING): it goes overdue, and a hold over its date takes it
130	 *  out of the live totals unless a statement binds it. */
131	export function isOpen(c: Claim): boolean {
132	  return c.status === 'OPEN' || c.status === 'PENDING';
133	}
134	
135	/** Whether a claim is bound by its person's last statement now: a PENDING claim too shows and totals
136	 *  the bound figure. */
137	export function bound(c: Claim): boolean {
138	  return c.stated;
139	}
140	
141	export interface ClaimFields {
142	  amount: string;
143	  /** Blank takes the sheet's today. */
144	  date: string;
145	  note: string;
146	  /** The number of the settled claim a negative amount corrects; blank for any other claim. */
147	  corrects: string;
148	  /** The external reference, surrounding spaces removed; blank for none. */
149	  ref: string;
150	  /** The tags, comma separated; blank for none. */
151	  tags: string;
152	}
153	
154	// The people's claims on the active sheet, newest first, re-read from the server each time the
155	// sheet is loaded. Sums are kept in whole cents so they add up exactly, and count only OPEN, PENDING
156	// and SETTLED claims.
157	@Injectable({ providedIn: 'root' })
158	export class Claims {
159	  private readonly http = inject(HttpClient);
160	  private readonly session = inject(Session);
161	  private readonly people = inject(People);
162	
163	  readonly claims = signal<Claim[]>([]);
164	  /** The tags the sheet's claims have carried, as last read from the server. */
165	  private readonly storedTags = signal<string[]>([]);
166	  /** Every tag ever used on the sheet, sorted: those stored and those its claims carry now. */
167	  readonly usedTags = computed(() =>
168	    [...new Set([...this.storedTags(), ...this.claims().flatMap((c) => c.tags)])].sort(),
169	  );
170	  /** The ids of the claims chosen for a bulk action. */
171	  readonly selected = signal<ReadonlySet<number>>(new Set());
172	  private loads = 0;
173	
174	  /** The claims that count in the live totals: those that count, less the OPEN and PENDING claims bound
175	   *  by no statement and dated within one of their person's holds or whose person's retirement date is
176	   *  reached, and the deferred claims. */
177	  readonly live = computed(() => {
178	    const leftOut = this.leftOut();
179	    return this.claims().filter((c) => counts(c) && !leftOut(c) && !this.deferred(c));
180	  });
181	
182	  /** The claims a period's figures may count, whatever their status: all but the OPEN and PENDING claims
183	   *  bound by no statement and dated within one of their person's holds, and the deferred claims, as the
184	   *  live totals leave those out. */
185	  readonly periodCandidates = computed(() => {
186	    const leftOut = this.leftOut();
187	    return this.claims().filter((c) => !leftOut(c) && !this.deferred(c));
188	  });
189	
190	  /** Whether a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound by no
191	   *  statement, and its person's retirement date is reached on the sheet's today. A hold no longer does. */
192	  private readonly leftOut = computed(() => {
193	    const today = this.session.today();
194	    const byId = new Map(this.people.people().map((p) => [p.id, p]));
195	    return (c: Claim): boolean => {
196	      const p = byId.get(c.personId);
197	      return isOpen(c) && !bound(c) && p !== undefined
198	        && retiredBy(p, today);
199	    };
200	  });
201	
202	  /** Whether a retirement leaves a claim out of claimed: it is OPEN or PENDING, bound by no statement,
203	   *  and its person's retirement date is reached on the sheet's today. */
204	  private readonly retiredOut = computed(() => {
205	    const today = this.session.today();
206	    const byId = new Map(this.people.people().map((p) => [p.id, p]));
207	    return (c: Claim): boolean => {
208	      const p = byId.get(c.personId);
209	      return isOpen(c) && !bound(c) && p !== undefined && retiredBy(p, today);
210	    };
211	  });
212	
213	  /** The claims that count toward claimed: those that count, less those a retirement leaves out and the
214	   *  deferred claims (a hold leaves a claim in claimed), leaving out claims that correct another. */
215	  private readonly counted = computed(() => {
216	    const retiredOut = this.retiredOut();
217	    return this.claims().filter((c) => counts(c) && !retiredOut(c) && !this.deferred(c) && !c.corrects);
218	  });
219	
220	  /** Each person's claimed, in cents, by person id. */
221	  readonly claimedCents = computed(() => {
222	    const out = new Map<number, number>();
223	    for (const c of this.counted()) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
224	    return out;
225	  });
226	
227	  /** Everyone's claimed added up, with two decimals. */
228	  readonly total = computed(() => money(this.counted().reduce((sum, c) => sum + cents(c.amount), 0)));
229	
230	  /** The date a claim is due by: fixed when it was added, from the terms of its person's grade then. */
231	  dueBy(c: Claim): string {
232	    return c.dueBy;
233	  }
234	
235	  /** The date a claim's lateness runs from: its due-by plus the grace days in force on its date of its
236	   *  person's grade in force then (none: the due-by). */
237	  lateFrom(c: Claim): string {
238	    const p = this.people.people().find((x) => x.id === c.personId);
239	    const grace = p === undefined ? 0 : this.session.graceOn(gradeOn(p.grades, c.date), c.date);
240	    return grace === 0 ? this.dueBy(c) : addDays(this.dueBy(c), grace);
241	  }
242	
243	  /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus its grace (see
244	   *  lateFrom) before the sheet's today. */
245	  overdue(c: Claim): boolean {
246	    const today = this.session.today();
247	    return isOpen(c) && !this.deferred(c) && today !== null && this.lateFrom(c) < today;
248	  }
249	
250	  /** Whether a REVIEW claim is late for review: its review day (the sheet's today when it last went to
251	   *  REVIEW, as its status log records it) plus the sheet's review SLA is before the sheet's today. Never
252	   *  while the sheet has no SLA. */
253	  reviewLate(c: Claim): boolean {
254	    const today = this.session.today();
255	    const sla = this.session.reviewSla();
256	    if (c.status !== 'REVIEW' || today === null || sla === null) return false;
257	    const went = c.statusLog.filter((l) => l.status === 'REVIEW').at(-1);
258	    return went !== undefined && addDays(went.on, sla) < today;
259	  }
260	
261	  /** Whether a claim shows as deferred: its deferred-until date is after the sheet's today, whatever its
262	   *  status (a deferred claim voided keeps showing it). Only an OPEN one is left out of totals (`deferred`). */
263	  deferredShown(c: Claim): boolean {
264	    const today = this.session.today();
265	    return c.deferredUntil !== null && today !== null && today < c.deferredUntil;
266	  }
267	
268	  /** Whether a claim is deferred: OPEN, with a deferred-until date after the sheet's today. Until then it
269	   *  counts in no total, is not overdue and cannot be settled. */
270	  deferred(c: Claim): boolean {
271	    const today = this.session.today();
272	    return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
273	  }
274	
275	  /** The late charge, in cents, on a claim's figure (in cents): while it is overdue, for each full 30 days
276	   *  past its due-by plus its grace (see lateFrom), the sheet's late percent in force on that boundary date
277	   *  (that date plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it, rounded to cents as its date rounds, the charges added up; none otherwise, and none
278	   *  on a correction or a waived claim. Frozen into the due when bound by a statement or settled. */
279	  lateCents(c: Claim, figureCents: bigint): bigint {
280	    const today = this.session.today();
281	    if (!this.overdue(c) || today === null || c.amount.startsWith('-') || c.waived) return 0n;
282	    const from = this.lateFrom(c);
283	    const periods = Math.floor(daysBetween(from, today) / 30);
284	    const halfUp = this.session.roundsHalfUp(c.date);
285	    let total = 0n;
286	    for (let k = 1; k <= periods; k++) {
287	      total += rounded((figureCents + total) * hundredths(this.session.latePctOn(addDays(from, 30 * k))), 10000n, halfUp);
288	    }
289	    return total;
290	  }
291	
292	  /** A claim's due from its figure (the rate figure, or the one its statement bound), in cents: the figure
293	   *  at least the sheet's floor in force on the claim's date, with the late charge worked out on that floored
294	   *  figure on top (the floor applied first); a correction takes neither charge nor floor, and a bound figure
295	   *  already holds both. */
296	  chargedCents(c: Claim, figureCents: bigint): bigint {
297	    if (c.amount.startsWith('-') || bound(c)) return figureCents;
298	    const floor = hundredths(this.session.floorOn(c.date));
299	    const floored = figureCents < floor ? floor : figureCents;
300	    return floored + this.lateCents(c, floored);
301	  }
302	
303	  /** The date a claim's figures round by: its own, or for a correction the date of the claim of the same
304	   *  person it corrects (its own when that is not found). */
305	  roundingDate(c: Claim): string {
306	    if (c.corrects === null) return c.date;
307	    return this.claims().find((o) => o.personId === c.personId && o.number === c.corrects)?.date ?? c.date;
308	  }
309	
310	  /** A person's claims, newest first. */
311	  of(personId: number): Claim[] {
312	    return this.claims().filter((c) => c.personId === personId);
313	  }
314	
315	  /** A person's claimed, with two decimals. */
316	  claimed(personId: number): string {
317	    return money(this.claimedCents().get(personId) ?? 0);
318	  }
319	
320	  /** Replace a person's claims with these, as the server answered them (newest first). */
321	  replaceOf(personId: number, theirs: Claim[]): void {
322	    const byId = new Map(theirs.map((c) => [c.id, c]));
323	    this.claims.update((cs) => cs.map((c) => (c.personId === personId ? (byId.get(c.id) ?? c) : c)));
324	  }
325	
326	  /** Re-read the active sheet's claims from the server; an error message when that failed. */
327	  async load(): Promise<string | null> {
328	    const user = this.session.user();
329	    const sid = this.session.sheetId();
330	    const load = ++this.loads;
331	    this.claims.set([]);
332	    this.storedTags.set([]);
333	    this.selected.set(new Set());
334	    if (!user || !sid) return null;
335	    try {
336	      const [claims, tags] = await Promise.all([
337	        firstValueFrom(this.http.get<Claim[]>(`${this.url(sid)}/claims`, { headers: { 'X-User': user } })),
338	        firstValueFrom(this.http.get<string[]>(`${this.url(sid)}/claim-tags`, { headers: { 'X-User': user } })),
339	      ]);
340	      if (load === this.loads) {
341	        this.claims.set(claims);
342	        this.storedTags.set(tags);
343	      }
344	      return null;
345	    } catch (e) {
346	      return failed('load', e).replace(' claim', ' claims');
347	    }
348	  }
349	
