62	  inForceFor(grade: string, date: string, claimId?: number): Rate | undefined {
63	    if (claimId === undefined) return this.inForce(grade, date);
64	    for (const rates of [this.rates(), ...this.inherited()]) {
65	      const found = inForceAmong(forClaim(rates, claimId), grade, date);
66	      if (found) return found;
