99	  /** Re-read the active sheet's rates from the server; an error message when that failed. */
100	  async load(): Promise<string | null> {
101	    const user = this.session.user();
102	    const sid = this.session.sheetId();
103	    const load = ++this.loads;
104	    this.rates.set([]);
105	    this.inherited.set([]);
106	    if (!user || !sid) return null;
107	    try {
108	      const [rates, inherited] = await Promise.all([
109	        firstValueFrom(this.http.get<Rate[]>(this.url(sid), { headers: { 'X-User': user } })),
110	        firstValueFrom(this.http.get<Rate[][]>(`${this.url(sid)}/inherited`, { headers: { 'X-User': user } })),
111	      ]);
112	      if (load === this.loads) {
113	        this.rates.set([...rates].sort(byGradeAndFrom));
114	        this.inherited.set(inherited.map((level) => [...level].sort(byGradeAndFrom)));
115	      }
116	      return null;
