122	  /** Set a grade's rate from a date (blank: from the beginning of time) through a to-date (blank:
123	   *  for good), replacing the one it had from that date; an error message when refused. */
124	  async set(grade: string, pct: string, from: string, to: string): Promise<string | null> {
125	    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
126	    if (!/^\d+(\.\d{1,2})?$/.test(pct.trim())) return 'Enter a rate of 0.00 or more, with up to two decimals.';
127	    if (from.trim() && !isDate(from.trim())) return 'Enter a from-date as YYYY-MM-DD, or leave it blank.';
128	    if (to.trim() && !isDate(to.trim())) return 'Enter a to-date as YYYY-MM-DD, or leave it blank.';
129	    if (to.trim() && from.trim() && to.trim() < from.trim()) return "A rate's to-date cannot be before its from-date.";
130	    const sid = this.session.sheetId()!;
131	    try {
132	      const rate = await firstValueFrom(
133	        this.http.put<Rate>(`${this.url(sid)}/${encodeURIComponent(grade)}`, { rate: pct.trim(), from: from.trim() || null, to: to.trim() || null }, {
134	          headers: { 'X-User': this.session.user()! },
135	        }),
136	      );
137	      if (this.session.sheetId() === sid) {
138	        this.rates.update((rs) =>
139	          [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate].sort(byGradeAndFrom),
140	        );
141	      }
142	      return null;
143	    } catch (e) {
144	      return failed('set', e);
145	    }
146	  }
