148	  /** Set the rate each pasted line of grade,rate,from,to names (from and to may be left out or blank),
149	   *  in order, as the form would; how many were set, or why the import was refused (then none was). */
150	  async importRates(text: string): Promise<number | string> {
151	    const sid = this.session.sheetId();
152	    const user = this.session.user();
153	    if (!user || !sid) return 'Load a sheet first.';
154	    if (!text.trim()) return 'Paste at least one line of grade,rate,from,to.';
155	    try {
156	      const done = await firstValueFrom(
157	        this.http.post<{ set: number; rates: Rate[] }>(`${this.url(sid)}/import`, { text }, {
158	          headers: { 'X-User': user },
159	        }),
160	      );
161	      if (this.session.sheetId() === sid) this.rates.set([...done.rates].sort(byGradeAndFrom));
162	      return done.set;
163	    } catch (e) {
164	      if (e instanceof HttpErrorResponse && e.status === 422 && typeof e.error?.message === 'string' && e.error.message) {
165	        return e.error.message;
166	      }
167	      return e instanceof HttpErrorResponse && e.status === 422
168	        ? 'A line could not be set; nothing was imported.'
169	        : failed('import', e).replace(' rate', ' rates');
170	    }
171	  }
