178	/** The grade's rate in force on a date among one sheet's rates (by grade then from-date), or undefined. */
179	function inForceAmong(rates: Rate[], grade: string, date: string): Rate | undefined {
180	  let found: Rate | undefined;
181	  for (const r of rates) {
182	    if (r.grade === grade && (r.from === null || r.from <= date)) found = r;
183	  }
184	  return found && (found.to === null || date <= found.to) ? found : undefined;
185	}
186	
187	/** One sheet's rates as they apply to a claim: a forward-only rate saved after the claim was added gives way
188	 *  to what applied to the claim before it, or is left out when nothing of that grade and from-date did. */
189	function forClaim(rates: Rate[], claimId: number): Rate[] {
190	  const out: Rate[] = [];
191	  for (const r of rates) {
192	    const e = r.earlier?.find((x) => claimId <= x.upTo);
193	    if (!e) out.push(r);
194	    else if (e.rate !== null) out.push({ ...r, rate: e.rate, to: e.to });
195	  }
196	  return out;
197	}
198	
199	/** By grade, then from-date, the one with none first. */
200	function byGradeAndFrom(a: Rate, b: Rate): number {
201	  return a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '');
202	}
