204	/** A number divided by a positive one, rounded half to even (a negative number as its opposite). */
205	export function halfEven(n: bigint, d: bigint): bigint {
206	  if (n < 0n) return -halfEven(-n, d);
207	  const q = n / d;
208	  const twice = (n % d) * 2n;
209	  return twice > d || (twice === d && q % 2n === 1n) ? q + 1n : q;
210	}
211	
212	/** A number divided by a positive one, rounded half up (away from zero) or half to even. */
213	export function rounded(n: bigint, d: bigint, halfUp: boolean): bigint {
214	  if (!halfUp) return halfEven(n, d);
215	  if (n < 0n) return -rounded(-n, d, true);
216	  const q = n / d;
217	  return (n % d) * 2n >= d ? q + 1n : q;
218	}
219	
220	/** A number written with up to two decimals, perhaps negative, in hundredths. */
221	export function hundredths(s: string): bigint {
222	  if (s.startsWith('-')) return -hundredths(s.slice(1));
223	  const [whole, frac = ''] = s.split('.');
224	  return BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
225	}
226	
227	/** Hundredths written with two decimals. */
228	export function money(h: bigint): string {
229	  if (h < 0n) return `-${money(-h)}`;
230	  return `${h / 100n}.${String(h % 100n).padStart(2, '0')}`;
231	}
232	
233	function failed(what: string, e: unknown): string {
234	  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a rate of 0.00 or more, with up to two decimals.';
235	  if (e instanceof HttpErrorResponse && e.status === 422) return "A rate's to-date cannot be before its from-date.";
236	  return e instanceof HttpErrorResponse ? `Could not ${what} rate (${e.status}).` : `Could not ${what} rate.`;
237	}
