592	   592	    }
593	   593	
594	   594	    /** The import box: lines of name,grade,terms,contact (the last two may be absent or blank; a blank
595	   595	     *  grade is the sheet's default grade), blank lines
596	   596	     *  skipped. A line whose name is a name or alias on the sheet (ignoring case) updates that person; any
597	   597	     *  other adds one. Every line is checked first with the person form's rules, a name, person or contact
598	   598	     *  repeated within the import too (ignoring case); a refused line refuses the import, changing no one and
599	   599	     *  writing nothing. Otherwise each is applied in order: an add exactly as the form adds, an update as the
600	   600	     *  form saves, keeping their name, recording the grade from the sheet's today, and setting their terms
601	   601	     *  and contact only when the line gives them. */
602	   602	    @Transactional
603	   603	    public ImportResult importPeople(String sheetId, String user, String text) {
604	   604	        String defaultGrade = defaultGrade(sheetId);
605	   605	        List<ImportLine> lines = new ArrayList<>();
606	   606	        Map<ImportLine, Person> matched = new HashMap<>();
607	   607	        Set<String> names = new HashSet<>();
608	   608	        Set<Long> matchedIds = new HashSet<>();
609	   609	        Set<String> contacts = new HashSet<>();
610	   610	        Set<String> tree = namesInTree(sheetId, null);
611	   611	        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
612	   612	        for (int i = 0; i < raw.length; i++) {
613	   613	            if (raw[i].isBlank()) {
614	   614	                continue;
615	   615	            }
616	   616	            ImportLine line = parseImport(i + 1, raw[i], defaultGrade);
617	   617	            String lower = line.name().toLowerCase(Locale.ROOT);
618	   618	            if (!names.add(lower)) {
619	   619	                throw importRefused(line.number(), "the name " + line.name() + " is already in this import.");
620	   620	            }
621	   621	            Person match = people.findByNameOrAlias(sheetId, line.name()).orElse(null);
622	   622	            if (match != null) {
623	   623	                if (!matchedIds.add(match.getId())) {
624	   624	                    throw importRefused(line.number(), match.getName() + " is already in this import.");
625	   625	                }
626	   626	                if (Stream.concat(Stream.of(match.getName()), match.getAliases().stream())
627	   627	                        .anyMatch(n -> tree.contains(n.toLowerCase(Locale.ROOT)))) {
628	   628	                    throw importRefused(line.number(), "the name " + match.getName() + " is already in use.");
629	   629	                }
630	   630	                matched.put(line, match);
631	   631	            } else if (tree.contains(lower)) {
632	   632	                throw importRefused(line.number(), "the name " + line.name() + " is already in use.");
633	   633	            }
634	   634	            if (line.contact() != null) {
635	   635	                if (!contacts.add(line.contact())) {
636	   636	                    throw importRefused(line.number(), "the contact " + line.contact() + " is already in this import.");
637	   637	                }
638	   638	                if (people.contactTaken(sheetId, line.contact(), match == null ? null : match.getId())) {
639	   639	                    throw importRefused(line.number(), "the contact " + line.contact() + " is already in use.");
640	   640	                }
641	   641	            }
642	   642	            lines.add(line);
643	   643	        }
644	   644	        if (lines.isEmpty()) {
645	   645	            throw new PersonImportException("Paste at least one line of name,grade,terms,contact.");
646	   646	        }
647	   647	        List<Person> added = new ArrayList<>();
648	   648	        List<Person> updated = new ArrayList<>();
649	   649	        for (ImportLine line : lines) {
650	   650	            Person match = matched.get(line);
651	   651	            try {
652	   652	                if (match == null) {
653	   653	                    added.add(add(sheetId, user, line.name(), line.grade(), line.terms(), line.contact()));
654	   654	                } else {
655	   655	                    Person now = people.findByIdAndSheetId(match.getId(), sheetId)
656	   656	                            .orElseThrow(PersonNotFoundException::new);
657	   657	                    updated.add(update(sheetId, user, now.getId(), now.getVersion(), now.getName(), line.grade(),
658	   658	                            null, line.terms() != null ? line.terms() : now.getTerms(), null,
659	   659	                            line.contact() != null ? line.contact() : now.getContact(), null, true));
660	   660	                }
661	   661	            } catch (PersonNameTakenException | PersonContactTakenException | PersonNotFoundException
662	   662	                    | PersonVersionConflictException e) {
663	   663	                // changed by another user at the same moment
664	   664	                throw importRefused(line.number(), e.getMessage());
665	   665	            }
666	   666	        }
667	   667	        return new ImportResult(added, updated);
668	   668	    }
