670	   670	    private static ImportLine parseImport(int number, String raw, String defaultGrade) {
671	   671	        String[] f = raw.split(",", 4);
672	   672	        String name = f[0].trim();
673	   673	        if (name.isEmpty()) {
674	   674	            throw importRefused(number, "enter a name.");
675	   675	        }
676	   676	        if (name.length() > 200) {
677	   677	            throw importRefused(number, "the name is too long.");
678	   678	        }
679	   679	        String grade = f.length > 1 ? f[1].trim() : "";
680	   680	        if (grade.isEmpty()) {
681	   681	            grade = defaultGrade;
682	   682	        }
683	   683	        if (!grade.matches("[ABC]")) {
684	   684	            throw importRefused(number, "choose a grade of A, B or C.");
685	   685	        }
686	   686	        String terms = f.length > 2 ? f[2].trim() : "";
687	   687	        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
688	   688	            throw importRefused(number, "enter the terms as a whole number of days, or leave them blank.");
689	   689	        }
690	   690	        String contact = f.length > 3 ? f[3].trim() : "";
691	   691	        if (contact.length() > 200) {
692	   692	            throw importRefused(number, "enter a contact of at most 200 characters.");
693	   693	        }
694	   694	        return new ImportLine(number, name, grade, terms.isEmpty() ? null : Integer.valueOf(terms),
695	   695	                contactKey(contact));
696	   696	    }
