712	   712	    /** As {@link #update}, recording their own terms (none: none of their own) from a date, keeping those
713	   713	     *  already recorded (replacing those from that same date), or from the beginning of time when no date is
714	   714	     *  given; and setting the tags they carry (normalised; none: kept as they are). */
715	   715	    @Transactional
716	   716	    public Person update(String sheetId, String user, long personId, long version, String name, String grade,
717	   717	            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, List<String> tags) {
718	   718	        return update(sheetId, user, personId, version, name, grade, gradeFrom, terms, termsFrom, contact, tags,
719	   719	                true);
720	   720	    }
721	   721	
722	   722	    /** As the person form saves, which (form) also refuses a name or alias some other sheet of the tree
723	   723	     *  uses, so a person who clashes keeps being refused until a rename leaves them clashing with no one. */
724	   724	    private Person update(String sheetId, String user, long personId, long version, String name, String grade,
725	   725	            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, List<String> tags,
726	   726	            boolean form) {
727	   727	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
728	   728	        if (person.getVersion() != version) {
729	   729	            throw new PersonVersionConflictException(person);
730	   730	        }
731	   731	        requireFreeName(sheetId, name.trim(), person.getId());
