15	/** The grade in force on a date (YYYY-MM-DD): the one whose from-date is the latest on or before it. */
16	export function gradeOn(grades: GradeFrom[], date: string): string {
17	  let found: string | undefined;
18	  for (const g of grades) {
19	    if (found === undefined || g.from === null || g.from <= date) found = g.grade;
20	  }
21	  return found ?? '';
22	}
