37	/** Whether one of the holds covers a date (YYYY-MM-DD). */
38	export function heldOn(holds: Hold[], date: string): boolean {
39	  return holds.some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
40	}
