42	/** Whether a person's retirement date is reached on a day (the sheet's today): it is on or before it. */
43	export function retiredBy(p: { retiredFrom: string | null }, today: string | null): boolean {
44	  return p.retiredFrom !== null && today !== null && p.retiredFrom <= today;
45	}
