135	// The people on the active sheet, in list order (by position), re-read from the server each
136	// time the sheet is loaded.
137	@Injectable({ providedIn: 'root' })
138	export class People {
139	  private readonly http = inject(HttpClient);
140	  private readonly session = inject(Session);
141	
142	  readonly people = signal<Person[]>([]);
143	  /** Whether the list shows retired people; belongs to the screen, so loading a sheet leaves it. */
144	  readonly showRetired = signal(false);
145	  /** The ids of the people chosen for a bulk grade or retire. */
146	  readonly selected = signal<ReadonlySet<number>>(new Set());
147	  private loads = 0;
148	
149	  /** Re-read the active sheet's people from the server; an error message when that failed. */
150	  async load(): Promise<string | null> {
151	    const user = this.session.user();
152	    const sid = this.session.sheetId();
153	    const load = ++this.loads;
154	    this.people.set([]);
155	    this.selected.set(new Set());
156	    if (!user || !sid) return null;
157	    try {
158	      const people = await firstValueFrom(
159	        this.http.get<Person[]>(this.url(sid), { headers: { 'X-User': user } }),
160	      );
161	      if (load === this.loads) this.people.set(people);
162	      return null;
163	    } catch (e) {
164	      return failed('load', e).replace(' person', ' people');
165	    }
166	  }
167	
168	  /** Add a person; an error message when refused. */
169	  async add(f: PersonFields): Promise<string | null> {
170	    const refused = this.check(f);
171	    if (refused) return refused;
172	    const sid = this.session.sheetId()!;
173	    try {
174	      const person = await firstValueFrom(
175	        this.http.post<Person>(this.url(sid), this.body(f), { headers: { 'X-User': this.session.user()! } }),
176	      );
177	      if (this.session.sheetId() === sid) this.people.update((ps) => [...ps, person]);
178	      return null;
179	    } catch (e) {
180	      return failed('add', e);
181	    }
182	  }
183	
184	  /** Update the person each pasted line of name,grade,terms,contact names, or add one, in order; how many
185	   *  were added and updated, or an error message when any line is refused (then the server changes none). */
186	  async importPeople(text: string): Promise<{ added: number; updated: number } | string> {
187	    const sid = this.session.sheetId();
188	    const user = this.session.user();
189	    if (!user || !sid) return 'Load a sheet first.';
190	    if (!text.trim()) return 'Paste at least one line of name,grade,terms,contact.';
191	    try {
192	      const done = await firstValueFrom(
193	        this.http.post<{ added: number; people: Person[]; updated: number; changed: Person[] }>(
194	          `${this.url(sid)}/import`,
195	          { text },
196	          { headers: { 'X-User': user } },
197	        ),
198	      );
199	      if (this.session.sheetId() === sid) {
200	        const changed = new Map(done.changed.map((p) => [p.id, p]));
201	        this.people.update((ps) => [...ps.map((p) => changed.get(p.id) ?? p), ...done.people]);
202	      }
203	      return { added: done.added, updated: done.updated };
204	    } catch (e) {
205	      return failed('add', e).replace(' person', ' people');
206	    }
207	  }
