209	  /** Change a person's name and grade, from the version the editor loaded; the refusal when
210	   *  refused, carrying the person as stored now when someone else saved them in the meantime. */
211	  async update(id: number, version: number, f: PersonFields): Promise<Refusal | null> {
212	    const refused = this.check(f);
213	    if (refused) return { error: refused };
214	    const sid = this.session.sheetId()!;
215	    const put = (person: Person) => {
216	      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
217	    };
