651	  /** The value of a dated setting in force on a date (YYYY-MM-DD): the one with the latest from-date on or
652	   *  before it; null when none is recorded by then, or the one in force is none. */
653	  valueOn(key: string, date: string): string | null {
654	    let found: DatedSetting | undefined;
655	    for (const s of this.settings()) {
656	      if (s.key === key && s.from <= date && (found === undefined || s.from > found.from)) found = s;
