682	  /** Whether a claim dated on a date rounds half up: by the rounding mode in force on that date; with none,
683	   *  it is before the policy date (the sheet's today when there is none); otherwise it rounds half to even. */
684	  roundsHalfUp(date: string): boolean {
685	    const mode = this.valueOn('rounding', date);
