977	/** The number of days from one date (YYYY-MM-DD) to another, worked out on the calendar. */
978	export function daysBetween(from: string, to: string): number {
979	  const [fy, fm, fd] = from.split('-').map(Number);
980	  const [ty, tm, td] = to.split('-').map(Number);
981	  return dayNumber(ty, tm, td) - dayNumber(fy, fm, fd);
982	}
983	
984	/** A date (YYYY-MM-DD) moved on a number of days, worked out on the calendar without the clock. */
985	export function addDays(date: string, days: number): string {
986	  const [y, m, d] = date.split('-').map(Number);
987	  return fromDayNumber(dayNumber(y, m, d) + days);
988	}
989	
990	/** Days since 1970-01-01 of a calendar date. */
991	function dayNumber(y: number, m: number, d: number): number {
992	  const yy = m <= 2 ? y - 1 : y;
993	  const era = Math.floor(yy / 400);
994	  const yoe = yy - era * 400;
995	  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
996	  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
997	  return era * 146097 + doe - 719468;
998	}
999	
1000	/** The calendar date (YYYY-MM-DD) of a number of days since 1970-01-01. */
1001	function fromDayNumber(n: number): string {
1002	  const z = n + 719468;
1003	  const era = Math.floor(z / 146097);
1004	  const doe = z - era * 146097;
1005	  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
1006	  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
1007	  const mp = Math.floor((5 * doy + 2) / 153);
1008	  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
1009	  const m = mp < 10 ? mp + 3 : mp - 9;
1010	  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
1011	  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
1012	}
