1014	/** A real calendar date written YYYY-MM-DD. */
1015	export function isDate(s: string): boolean {
1016	  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
1017	  if (!m) return false;
1018	  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
1019	  const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
1020	  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
1021	  return mo >= 1 && mo <= 12 && d >= 1 && d <= days[mo - 1];
1022	}
