52:    /** People's figures added up, leaving out the single highest and the single lowest when there are three
53:     *  or more. */
54:    static BigDecimal trimmed(List<BigDecimal> figures) {
55:        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
56:        if (figures.size() < 3) {
57:            return sum;
58:        }
59:        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
60:        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
61:        return sum.subtract(max).subtract(min);
