522	   522	     *  from (its due-by plus any grace, see lateFrom) on the sheet's today, the late percent in force on that
523	   523	     *  boundary date (that date plus 30, 60, 90 ... days) of the
524	   524	     *  figure plus the charges of the boundaries before it (compounding), rounded to cents as its date
525	   525	     *  rounds, the charges added up (a boundary at 0.00 adds nothing);
526	   526	     *  0.00 for no figure (n/a). Only an OPEN or PENDING claim is overdue, so the caller asks only for those. */
527	   527	    public BigDecimal lateCharge(BigDecimal figure, LocalDate lateFrom, LocalDate date) {
528	   528	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
529	   529	        if (figure == null) {
530	   530	            return charge;
531	   531	        }
532	   532	        long boundaries = ChronoUnit.DAYS.between(lateFrom, today) / 30;
533	   533	        RoundingMode rounding = rounding(date);
534	   534	        for (long k = 1; k <= boundaries; k++) {
535	   535	            charge = charge.add(figure.add(charge).multiply(latePctOn(lateFrom.plusDays(30 * k))).movePointLeft(2)
536	   536	                    .setScale(2, rounding));
537	   537	        }
538	   538	        return charge;
539	   539	    }
