998	   998	            List<Sheet> tree = sheets.tree(id).stream().sorted()
999	   999	                    .map(other -> sheets.findForUpdateById(other).orElse(null))
1000	  1000	                    .filter(Objects::nonNull).toList();
1001	  1001	            int fiscalYear = sheet.fiscalYearOf(date);
1002	  1002	            List<String> others = tree.stream().map(Sheet::getId).toList();
1003	  1003	            int lastOfTree = fiscalSequences.findBySheetIdInAndFiscalYear(others, fiscalYear).stream()
1004	  1004	                    .mapToInt(FiscalClaimSequence::getLastNumber).max().orElse(0);
1005	  1005	            FiscalClaimSequence sequence = fiscalSequences.findBySheetIdAndFiscalYear(id, fiscalYear)
1006	  1006	                    .orElseGet(() -> new FiscalClaimSequence(id, fiscalYear));
1007	  1007	            String number = sequence.nextClaimNumber(lastOfTree);
1008	  1008	            fiscalSequences.save(sequence);
