496	   496	 * Clones a sheet to another id never used: its today, settings, roles, rates, holidays, void reasons,
497	   497	 * templates, people (with all they carry but their watches and statements), pools, crews, periods (all open) and
498	   498	 * claims (statement bindings dropped, numbers given afresh by the clone's own numbering).
499	   499	 */
500	   500	@Service
501	   501	public class SheetCloneService {
502	   502	
503	   503	    private final JdbcTemplate jdbc;
504	   504	    private final SheetRepository sheets;
505	   505	    private final SheetService sheetService;
506	   506	    private final RoleService roles;
