516	   516	
517	   517	    public SheetCloneService(JdbcTemplate jdbc, SheetRepository sheets, SheetService sheetService, RoleService roles,
518	   518	            Rollup rollup, Audit audit, History history, PersonRepository people, ClaimRepository claims,
519	   519	            RateRepository rates, PeriodRepository periods, PatronRepository patrons, SheetRoleRepository sheetRoles) {
520	   520	        this.jdbc = jdbc;
521	   521	        this.sheets = sheets;
522	   522	        this.sheetService = sheetService;
523	   523	        this.roles = roles;
524	   524	        this.rollup = rollup;
525	   525	        this.audit = audit;
526	   526	        this.history = history;
527	   527	        this.people = people;
528	   528	        this.claims = claims;
529	   529	        this.rates = rates;
