534	   534	
535	   535	    /** A steward clones the sheet to another id, which must never have been used. Writes SHEET_CLONE_MADE on
536	   536	     *  this sheet, and SHEET_CLONED then a ROLLUP line of every person and the TOTALS on the clone. */
537	   537	    @Transactional
538	   538	    public Sheet cloneSheet(String id, String user, String to) {
539	   539	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
540	   540	        if (!roles.isSteward(id, user)) {
541	   541	            throw new ActionNotAllowedException("clone the sheet");
542	   542	        }
543	   543	        String target = to == null ? "" : to.trim();
544	   544	        if (target.isEmpty()) {
545	   545	            throw new CloneRefusedException("Enter the id of the sheet to clone to.");
546	   546	        }
547	   547	        if (sheets.existsById(target)) {
548	   548	            throw new CloneRefusedException("The sheet to clone to must be one never used.");
549	   549	        }
550	   550	        copySheet(sheet, target, user);
551	   551	        Map<Long, Long> personIds = copyPeople(id, target);
552	   552	        copyPools(id, target, personIds);
553	   553	        copyCrews(id, target, personIds);
554	   554	        copyPeriods(id, target);
555	   555	        List<long[]> claimIds = copyClaims(id, target, personIds);
556	   556	        remapRates(target, claimIds);
557	   557	        keepHistory(target);
558	   558	        audit.recordOnCommit("SHEET_CLONE_MADE sheet=" + id + " by=" + user + " to=" + target);
