671	   671	            long oldId = ((Number) c.get("id")).longValue();
672	   672	            long oldPerson = ((Number) c.get("person_id")).longValue();
673	   673	            long newId = insert("INSERT INTO claim (sheet_id, person_id, list_order, amount, claim_date, due_by, terms,"
674	   674	                    + " note, status, corrects_number, settled_due, opened_by, edited_by, stated, stated_due,"
