676	   676	                    + " tags, escalated, waived, proof_photos, held) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, FALSE, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
677	   677	                    target, personIds.get(oldPerson), c.get("list_order"), c.get("amount"), c.get("claim_date"),
678	   678	                    c.get("due_by"), c.get("terms"), c.get("note"), c.get("status"), c.get("corrects_number"),
679	   679	                    c.get("settled_due"), c.get("opened_by"), c.get("edited_by"), c.get("deferred_until"),
680	   680	                    c.get("proofs"), c.get("split_from"), c.get("settle_batch"), c.get("late_entry"),
681	   681	                    c.get("reminded_on"), c.get("ref"), c.get("void_reason"), c.get("tags"),
682	   682	                    c.get("escalated"), c.get("waived"), c.get("proof_photos"), c.get("held"));
683	   683	            copied.add(new long[] { oldId, newId });
684	   684	            jdbc.update("INSERT INTO claim_status_log (claim_id, seq, status, by_user, on_date, due)"
685	   685	                    + " SELECT ?, seq, status, by_user, on_date, due FROM claim_status_log WHERE claim_id = ?",
