689	   689	                    newId, oldId);
690	   690	            String number = (String) c.get("claim_number");
691	   691	            if (number != null) {
692	   692	                LocalDate openedOn = jdbc.queryForList("SELECT on_date FROM claim_status_log WHERE claim_id = ?"
693	   693	                        + " AND status = 'OPEN' ORDER BY seq", Date.class, oldId).stream().findFirst()
694	   694	                        .map(Date::toLocalDate).orElse(((Date) c.get("claim_date")).toLocalDate());
695	   695	                numbered.add(new Numbered(newId, number, ((Date) c.get("due_by")).toLocalDate(), openedOn,
696	   696	                        positions.getOrDefault(oldPerson, 0L), oldId));
