718	   718	    /** A forward-only rate of the clone keeps applying only to the claims that came after it: each claim id its
719	   719	     *  earlier entries name becomes the new id of the last claim copied with an id at most that (copied in id
720	   720	     *  order), or 0 when none was. */
721	   721	    private void remapRates(String target, List<long[]> claimIds) {
722	   722	        for (Map<String, Object> r : jdbc.queryForList("SELECT id, earlier FROM rate WHERE sheet_id = ?"
723	   723	                + " AND earlier IS NOT NULL", target)) {
724	   724	            String earlier = Rate.remapEarlier((String) r.get("earlier"), upTo -> {
725	   725	                long mapped = 0;
726	   726	                for (long[] ids : claimIds) {
727	   727	                    if (ids[0] <= upTo) {
728	   728	                        mapped = ids[1];
729	   729	                    }
730	   730	                }
731	   731	                return mapped;
732	   732	            });
733	   733	            jdbc.update("UPDATE rate SET earlier = ? WHERE id = ?", earlier, r.get("id"));
734	   734	        }
735	   735	    }
