752	   752	    private long insert(String sql, Object... args) {
753	   753	        KeyHolder keys = new GeneratedKeyHolder();
754	   754	        jdbc.update(con -> {
755	   755	            PreparedStatement ps = con.prepareStatement(sql, new String[] { "ID" });
756	   756	            for (int i = 0; i < args.length; i++) {
757	   757	                ps.setObject(i + 1, args[i]);
758	   758	            }
759	   759	            return ps;
760	   760	        }, keys);
761	   761	        return keys.getKey().longValue();
762	   762	    }
