775	   775	/**
776	   776	 * An archived sheet stays visible and changes nothing: every change to it is refused before it reaches its
777	   777	 * handler. Loading the sheet is not a change; archiving refuses an archived sheet itself, and a bulk action
778	   778	 * goes through with nothing done (each claim refused), so those are left to their handlers.
779	   779	 */
780	   780	@Configuration
781	   781	public class ArchivedGuard implements WebMvcConfigurer, HandlerInterceptor {
782	   782	
783	   783	    private final SheetService sheets;
784	   784	
785	   785	    public ArchivedGuard(SheetService sheets) {
786	   786	        this.sheets = sheets;
787	   787	    }
788	   788	
789	   789	    @Override
790	   790	    public void addInterceptors(InterceptorRegistry registry) {
791	   791	        registry.addInterceptor(this)
792	   792	                .addPathPatterns("/api/sheets/*/**")
793	   793	                .excludePathPatterns("/api/sheets/*/load", "/api/sheets/*/archive", "/api/sheets/*/claims/bulk-*");
794	   794	    }
795	   795	
796	   796	    @Override
797	   797	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
798	   798	        if ("GET".equals(request.getMethod()) || "HEAD".equals(request.getMethod())
799	   799	                || "OPTIONS".equals(request.getMethod())) {
800	   800	            return true;
801	   801	        }
802	   802	        @SuppressWarnings("unchecked")
803	   803	        Map<String, String> vars = (Map<String, String>) request
804	   804	                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
805	   805	        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
806	   806	        if (sheetId != null) {
807	   807	            sheets.requireNotArchived(sheetId.trim());
808	   808	        }
809	   809	        return true;
810	   810	    }
811	   811	}
