961	   961	public interface SheetRepository extends JpaRepository<Sheet, String> {
962	   962	
963	   963	    /** The sheet, locked until the transaction ends, so two users' claim numbers go one after the other. */
964	   964	    @Lock(LockModeType.PESSIMISTIC_WRITE)
965	   965	    @Query("select s from Sheet s where s.id = :id")
966	   966	    Optional<Sheet> findForUpdateById(String id);
967	   967	
968	   968	    /** The sheets naming this one as their parent: its children. */
969	   969	    List<Sheet> findByParentOrderByIdAsc(String parent);
970	   970	
971	   971	    /** How many levels up a sheet's rates are taken from its ancestors. */
972	   972	    int ANCESTOR_LEVELS = 3;
973	   973	
974	   974	    /** The sheets whose rates a grade with no rate in force on a date here takes, nearest first: the sheet's
975	   975	     *  parent, the parent's parent and so on up to three levels up; then, for a clone, the sheet it was cloned
976	   976	     *  from and that sheet's own ancestors the same way (its parents, then its source), and so on. */
977	   977	    default List<String> ancestors(String id) {
978	   978	        List<String> found = new ArrayList<>();
979	   979	        String from = id;
980	   980	        while (from != null) {
981	   981	            String at = from;
982	   982	            int levels = 0;
983	   983	            while (levels < ANCESTOR_LEVELS) {
984	   984	                String parent = findById(at).map(Sheet::getParent).orElse(null);
985	   985	                if (parent == null || parent.equals(id) || found.contains(parent)) {
986	   986	                    break;
987	   987	                }
988	   988	                found.add(parent);
989	   989	                levels++;
990	   990	                at = parent;
991	   991	            }
992	   992	            String source = findById(from).map(Sheet::getSource).orElse(null);
993	   993	            if (source == null || source.equals(id) || found.contains(source)) {
994	   994	                break;
995	   995	            }
996	   996	            found.add(source);
997	   997	            from = source;
998	   998	        }
999	   999	        return found;
1000	  1000	    }
1001	  1001	
1002	  1002	    /** The other sheets of the sheet's tree: all its ancestors, however far up, and all its descendants and
1003	  1003	     *  theirs, among the sheets that exist. */
1004	  1004	    default Set<String> tree(String id) {
1005	  1005	        Set<String> found = new LinkedHashSet<>();
1006	  1006	        String at = findById(id).map(Sheet::getParent).orElse(null);
1007	  1007	        while (at != null && !at.equals(id) && found.add(at)) {
1008	  1008	            at = findById(at).map(Sheet::getParent).orElse(null);
1009	  1009	        }
1010	  1010	        Deque<String> next = new ArrayDeque<>(List.of(id));
1011	  1011	        while (!next.isEmpty()) {
1012	  1012	            for (Sheet child : findByParentOrderByIdAsc(next.pop())) {
1013	  1013	                if (!child.getId().equals(id) && found.add(child.getId())) {
1014	  1014	                    next.add(child.getId());
1015	  1015	                }
1016	  1016	            }
1017	  1017	        }
1018	  1018	        found.removeIf(s -> !existsById(s));
1019	  1019	        return found;
1020	  1020	    }
1021	  1021	}
