14	    14	
15	    15	/**
16	    16	 * The opening balances paste: lines of name,period,amount, each adding its amount to the opening balance of
17	    17	 * the person on the sheet with the name or an alias (ignoring case) for the period on the sheet with the name
18	    18	 * (ignoring case), and so to their carried figure for it. The amount has up to two decimals and is 0.00 or more.
19	    19	 * Blank lines are skipped. Every line is checked first; a refused line refuses the paste, adding nothing and
20	    20	 * writing nothing.
21	    21	 */
22	    22	@Service
23	    23	public class OpeningService {
24	    24	
25	    25	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}(\\.\\d{1,2})?");
26	    26	
27	    27	    private final PeriodRepository periods;
28	    28	    private final PersonRepository people;
29	    29	    private final SheetRepository sheets;
30	    30	    private final Audit audit;
31	    31	
32	    32	    public OpeningService(PeriodRepository periods, PersonRepository people, SheetRepository sheets, Audit audit) {
33	    33	        this.periods = periods;
34	    34	        this.people = people;
35	    35	        this.sheets = sheets;
36	    36	        this.audit = audit;
37	    37	    }
38	    38	
39	    39	    private record Line(Person person, Period period, BigDecimal amount) {
40	    40	    }
41	    41	
42	    42	    /** Paste opening balances: how many lines went through. */
43	    43	    @Transactional
44	    44	    public int paste(String sheetId, String user, String text) {
45	    45	        // Locking the sheet makes two users' pastes, and a close, go one after the other.
46	    46	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
47	    47	        List<Period> sheetPeriods = periods.findBySheetIdOrderByFromDateAsc(sheetId);
48	    48	        List<Line> lines = new ArrayList<>();
49	    49	        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
50	    50	        for (int i = 0; i < raw.length; i++) {
51	    51	            if (!raw[i].isBlank()) {
52	    52	                lines.add(parse(sheetId, sheetPeriods, i + 1, raw[i]));
53	    53	            }
54	    54	        }
55	    55	        if (lines.isEmpty()) {
56	    56	            throw new PeriodRefusedException("Paste at least one line of name,period,amount.");
57	    57	        }
58	    58	        for (Line line : lines) {
59	    59	            line.period().addOpening(line.person().getId(), line.amount());
60	    60	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
61	    61	                    + " period=" + line.period().getName() + " amount=" + line.amount().toPlainString());
62	    62	        }
63	    63	        lines.stream().map(Line::period).distinct().forEach(periods::saveAndFlush);
64	    64	        return lines.size();
65	    65	    }
66	    66	
67	    67	    private Line parse(String sheetId, List<Period> sheetPeriods, int number, String raw) {
68	    68	        String[] f = raw.split(",", -1);
69	    69	        if (f.length != 3) {
70	    70	            throw refused(number, "enter name,period,amount.");
71	    71	        }
72	    72	        String name = f[0].trim();
73	    73	        if (name.isEmpty() || name.length() > 200) {
74	    74	            throw refused(number, "enter a name.");
75	    75	        }
76	    76	        Person person = people.findByNameOrAlias(sheetId, name)
77	    77	                .orElseThrow(() -> refused(number, "no one on the sheet is named " + name + "."));
78	    78	        String periodName = f[1].trim();
79	    79	        Period period = sheetPeriods.stream().filter(p -> p.getName().equalsIgnoreCase(periodName)).findFirst()
80	    80	                .orElseThrow(() -> refused(number, "no period on the sheet is named " + periodName + "."));
81	    81	        String amount = f[2].trim();
82	    82	        if (!AMOUNT.matcher(amount).matches()) {
83	    83	            throw refused(number, "enter an amount of 0.00 or more with up to two decimals.");
84	    84	        }
85	    85	        return new Line(person, period, new BigDecimal(amount).setScale(2));
86	    86	    }
87	    87	
88	    88	    private static PeriodRefusedException refused(int number, String why) {
89	    89	        return new PeriodRefusedException("Line " + number + ": " + why);
90	    90	    }
91	    91	}
