618	   618	    @Transactional(readOnly = true)
619	   619	    public List<Period> list(String sheetId) {
620	   620	        if (!sheets.existsById(sheetId)) {
621	   621	            throw new SheetNotFoundException();
622	   622	        }
623	   623	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
624	   624	    }
625	   625	
626	   626	    @Transactional
627	   627	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
628	   628	        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
629	   629	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
630	   630	        String n = name.trim();
631	   631	        if (from.isAfter(to)) {
632	   632	            throw new PeriodRefusedException("The from-date must be on or before the to-date.");
633	   633	        }
634	   634	        if (cap != null && cap < 1) {
635	   635	            throw new PeriodRefusedException("The cap must be a whole number of 1 or more.");
636	   636	        }
637	   637	        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
638	   638	        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(n))) {
639	   639	            throw new PeriodRefusedException("That period name is already in use.");
640	   640	        }
641	   641	        existing.stream().filter(p -> p.overlaps(from, to)).findFirst().ifPresent(p -> {
642	   642	            throw new PeriodRefusedException("The period overlaps " + p.getName() + ".");
643	   643	        });
644	   644	        Period period;
645	   645	        try {
646	   646	            period = periods.saveAndFlush(new Period(sheetId, n, from, to, cap));
647	   647	        } catch (DataIntegrityViolationException e) {
648	   648	            throw new PeriodRefusedException("That period name is already in use.");
649	   649	        }
650	   650	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
651	   651	                + " period=" + n + " from=" + from + " to=" + to + (cap != null ? " cap=" + cap : ""));
652	   652	        return period;
653	   653	    }
654	   654	
655	   655	    /** Generate one period per calendar month from the from-date's month to the to-date's month, each from
656	   656	     *  the first to the last day of its month and named yyyy-mm; a month whose name is taken or whose days
657	   657	     *  overlap a period on the sheet is left out. A blank from-date takes the sheet's today. Refused when
658	   658	     *  the to-date is before the from-date. The periods made, in order. */
659	   659	    @Transactional
660	   660	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
661	   661	        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
662	   662	        Sheet sheet = sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
663	   663	        LocalDate start = from == null ? sheet.getToday() : from;
664	   664	        if (to.isBefore(start)) {
665	   665	            throw new PeriodRefusedException("The to-date must be on or after the from-date.");
666	   666	        }
667	   667	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
668	   668	        List<Period> made = new ArrayList<>();
669	   669	        for (YearMonth m = YearMonth.from(start); !m.isAfter(YearMonth.from(to)); m = m.plusMonths(1)) {
670	   670	            makeUnlessTaken(sheetId, user, m.toString(), m.atDay(1), m.atEndOfMonth(), existing, made);
671	   671	        }
672	   672	        return made;
673	   673	    }
674	   674	
675	   675	    /** Generate the four calendar quarters of a year, named yyyy-Q1 to yyyy-Q4, each as the period form
676	   676	     *  would add it; a quarter whose name is taken or whose days overlap a period on the sheet is left out.
677	   677	     *  The periods made, in order. */
678	   678	    @Transactional
679	   679	    public List<Period> generateQuarters(String sheetId, String user, int year) {
680	   680	        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
681	   681	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
682	   682	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
683	   683	        List<Period> made = new ArrayList<>();
684	   684	        for (int q = 1; q <= 4; q++) {
685	   685	            YearMonth firstMonth = YearMonth.of(year, q * 3 - 2);
686	   686	            makeUnlessTaken(sheetId, user, String.format("%04d-Q%d", year, q), firstMonth.atDay(1),
687	   687	                    firstMonth.plusMonths(2).atEndOfMonth(), existing, made);
688	   688	        }
689	   689	        return made;
690	   690	    }
691	   691	
692	   692	    /** Make a period from first to last unless its name is taken or its days overlap one of the existing
693	   693	     *  periods, adding it to both lists. */
694	   694	    private void makeUnlessTaken(String sheetId, String user, String name, LocalDate first, LocalDate last,
695	   695	            List<Period> existing, List<Period> made) {
696	   696	        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(name) || p.overlaps(first, last))) {
697	   697	            return;
698	   698	        }
699	   699	        Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
700	   700	        existing.add(period);
701	   701	        made.add(period);
702	   702	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
703	   703	                + " period=" + name + " from=" + first + " to=" + last);
704	   704	    }
705	   705	
706	   706	    /** Generate the twelve monthly periods of a fiscal year, exactly as {@link #generate} does from the
707	   707	     *  first month of the year to its last: the fiscal year starts on the first day of the sheet's fiscal
708	   708	     *  start month in the year it is named by. The periods made, in order. */
709	   709	    @Transactional
710	   710	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
711	   711	        // Locking the sheet first reads the fiscal start month as it stands while the periods are made.
712	   712	        Sheet sheet = sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
713	   713	        LocalDate first = LocalDate.of(year, sheet.getFiscalStartMonth(), 1);
714	   714	        return generate(sheetId, user, first, first.plusYears(1).minusDays(1));
715	   715	    }
