718	   718	     *  close it, or it is already closed. A soft-closed period can be closed, fixing its figures afresh. */
719	   719	    @Transactional
720	   720	    public Period close(String sheetId, String user, long periodId) {
721	   721	        // Locking the sheet makes the close and any claim change on the sheet go one after the other.
722	   722	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
723	   723	        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
724	   724	        roles.require(sheetId, user, "close");
725	   725	        if (period.isClosed()) {
726	   726	            throw new PeriodRefusedException("The period is already closed.");
727	   727	        }
728	   728	        return closeNow(sheetId, user, period, false);
