731	   731	    /** Soft-close a period, fixing each person's due-total and carried figure for it and its own as it is now while its claims
732	   732	     *  can still change; refused when the user's role may not close it, or it is already closed or
733	   733	     *  soft-closed. */
734	   734	    @Transactional
735	   735	    public Period softClose(String sheetId, String user, long periodId) {
736	   736	        // Locking the sheet makes the soft close and any claim change on the sheet go one after the other.
737	   737	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
738	   738	        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
739	   739	        roles.require(sheetId, user, "close");
740	   740	        if (period.isClosed() || period.isSoftClosed()) {
741	   741	            throw new PeriodRefusedException("The period is already closed.");
742	   742	        }
743	   743	        period.softClose(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()),
744	   744	                rollup.carriedByPerson(sheetId, period, periods.findBySheetIdOrderByFromDateAsc(sheetId)));
745	   745	        periods.saveAndFlush(period);
746	   746	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user
747	   747	                + " period=" + period.getName() + " total=" + period.getClosedTotal().toPlainString());
748	   748	        return period;
749	   749	    }
