751	   751	    /** Close, in order of their to-dates, every open period whose to-date plus the grace days is before the
752	   752	     *  sheet's (new) today, each as a close by hand would (a soft-closed period keeps its fixed figures); none
753	   753	     *  when the grace days are off. The caller holds the sheet's lock. */
754	   754	    @Transactional
755	   755	    public void closeOverdue(String sheetId, String user, LocalDate today, Integer graceDays) {
756	   756	        if (graceDays == null) {
757	   757	            return;
758	   758	        }
759	   759	        periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
760	   760	                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
761	   761	                .sorted(Comparator.comparing(Period::getToDate))
762	   762	                .forEach(p -> closeNow(sheetId, user, p, true));
763	   763	    }
