765	   765	    private Period closeNow(String sheetId, String user, Period period, boolean auto) {
766	   766	        period.close(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()),
767	   767	                rollup.carriedByPerson(sheetId, period, periods.findBySheetIdOrderByFromDateAsc(sheetId)));
