770	   770	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user
771	   771	                + " period=" + period.getName() + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
772	   772	        return period;
773	   773	    }
