779	   779	        // Locking the sheet makes the reopen and any claim change on the sheet go one after the other.
780	   780	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
781	   781	        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
782	   782	        roles.require(sheetId, user, "reopen");
