126	function cents(amount: string): bigint {
127	  const negative = amount.startsWith('-');
128	  const [whole, frac = ''] = amount.replace('-', '').split('.');
129	  const h = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
130	  return negative ? -h : h;
131	}
