433	   433	    @Transactional
434	   434	    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
435	   435	        requireSheet(sheetId);
436	   436	        if (to != null && from != null && to.isBefore(from)) {
437	   437	            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
438	   438	        }
439	   439	        BigDecimal value = pct.setScale(2);
440	   440	        Rollup.Snapshot before = rollup.take(sheetId);
441	   441	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
442	   442	        boolean forward = from != null && today != null && !from.isBefore(today);
443	   443	        // every claim added later has a higher id than those on the sheet now
444	   444	        long forwardAfter = forward ? claims.maxId() : 0;
445	   445	        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from).orElse(null);
446	   446	        if (rate == null) {
447	   447	            try {
448	   448	                rate = rates.saveAndFlush(forward ? new Rate(sheetId, grade, from, to, value, forwardAfter)
449	   449	                        : new Rate(sheetId, grade, from, to, value));
450	   450	            } catch (DataIntegrityViolationException e) {
451	   451	                // Another user set the same grade and from-date's first rate at the same moment.
452	   452	                throw new RateConflictException();
453	   453	            }
454	   454	        } else {
455	   455	            versions.save(new RateVersion(rate, user));
456	   456	            if (forward) {
457	   457	                rate.newVersion(value, to, forwardAfter);
458	   458	            } else {
459	   459	                rate.newVersion(value, to);
460	   460	            }
461	   461	            rate = rates.saveAndFlush(rate);
462	   462	        }
463	   463	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
464	   464	                + " grade=" + grade + " rate=" + rate.getRate().toPlainString()
465	   465	                + (from == null ? "" : " from=" + from)
466	   466	                + (to == null ? "" : " to=" + to));
467	   467	        rollup.recordChanges(sheetId, user, before);
468	   468	        return rate;
469	   469	    }
