471	   471	    /** One line of the rate import box: a grade's rate from a date through a date, either perhaps none. */
472	   472	    private record ImportLine(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
473	   473	    }
474	   474	
475	   475	    private static final Pattern GRADE = Pattern.compile("[ABC]");
476	   476	    private static final Pattern PCT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");
477	   477	
478	   478	    /** Set the rate each line of grade,rate,from,to names (from and to may be left out or blank), in order,
479	   479	     *  each as the rate form would; every line is checked first, and one refused line refuses them all.
480	   480	     *  Blank lines are skipped. How many were set. */
481	   481	    @Transactional
482	   482	    public int importRates(String sheetId, String user, String text) {
483	   483	        requireSheet(sheetId);
484	   484	        List<ImportLine> lines = new ArrayList<>();
485	   485	        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
486	   486	        for (int i = 0; i < raw.length; i++) {
487	   487	            if (!raw[i].isBlank()) {
488	   488	                lines.add(parseImport(i + 1, raw[i]));
489	   489	            }
490	   490	        }
491	   491	        if (lines.isEmpty()) {
492	   492	            throw new RateRefusedException("Paste at least one line of grade,rate,from,to.");
493	   493	        }
494	   494	        for (ImportLine line : lines) {
495	   495	            set(sheetId, user, line.grade(), line.from(), line.to(), line.pct());
496	   496	        }
497	   497	        return lines.size();
498	   498	    }
499	   499	
500	   500	    private static ImportLine parseImport(int number, String line) {
501	   501	        String[] f = line.split(",", -1);
502	   502	        if (f.length < 2 || f.length > 4) {
503	   503	            throw importRefused(number, "write it as grade,rate,from,to.");
504	   504	        }
505	   505	        String grade = f[0].trim();
506	   506	        if (!GRADE.matcher(grade).matches()) {
507	   507	            throw importRefused(number, "the grade must be A, B or C.");
508	   508	        }
509	   509	        String pct = f[1].trim();
510	   510	        if (!PCT.matcher(pct).matches()) {
511	   511	            throw importRefused(number, "enter a rate of 0.00 or more, with up to two decimals.");
512	   512	        }
513	   513	        LocalDate from = importDate(number, f.length > 2 ? f[2] : "", "from-date");
514	   514	        LocalDate to = importDate(number, f.length > 3 ? f[3] : "", "to-date");
515	   515	        if (from != null && to != null && to.isBefore(from)) {
516	   516	            throw importRefused(number, "a rate's to-date cannot be before its from-date.");
517	   517	        }
518	   518	        return new ImportLine(grade, new BigDecimal(pct), from, to);
519	   519	    }
520	   520	
521	   521	    private static LocalDate importDate(int number, String field, String what) {
522	   522	        String d = field.trim();
523	   523	        if (d.isEmpty()) {
524	   524	            return null;
525	   525	        }
526	   526	        try {
527	   527	            if (d.length() != 10) {
528	   528	                throw new DateTimeParseException(d, d, 0);
529	   529	            }
530	   530	            return LocalDate.parse(d);
531	   531	        } catch (DateTimeParseException e) {
532	   532	            throw importRefused(number, "enter a " + what + " as YYYY-MM-DD, or leave it blank.");
533	   533	        }
534	   534	    }
535	   535	
536	   536	    private static RateRefusedException importRefused(int number, String why) {
537	   537	        return new RateRefusedException("Line " + number + ": " + why);
538	   538	    }
539	   539	
540	   540	    private void requireSheet(String sheetId) {
541	   541	        if (!sheets.existsById(sheetId)) {
542	   542	            throw new SheetNotFoundException();
543	   543	        }
544	   544	    }
