671	   671	
672	   672	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
673	   673	
674	   674	    /** A member, a person or another pool (poolId set, never retired): a retired person (a retirement date set,
675	   675	     *  whatever the date) counts its share toward the total but is left out of the cuts (0.00, its share spread
676	   676	     *  over the others; none when every member is retired). Its cut of the pool's pot (two decimals; 0.00 for a person
677	   677	     *  on hold on the sheet's today, whose share is spread over the others); none when the pool is unbalanced or
678	   678	     *  has no pot. A member whose dates (from, to: optional) do not include the sheet's today is left out
679	   679	     *  entirely: it counts 0.00 toward the total and has no cut. Its cut at the end of each period whose to-date is
680	   680	     *  on or before the sheet's today, by from-date (cuts). */
681	   681	    public record PoolMemberView(Long personId, Long poolId, String name, String share, boolean retired, String cut,
682	   682	            LocalDate from, LocalDate to, boolean active, List<PeriodCut> cuts) {
683	   683	
684	   684	        PoolMemberView withCuts(List<PeriodCut> cuts) {
