691	   691	        }
692	   692	    }
693	   693	
694	   694	    /** A member's cut as it stood at the end of a period (its to-date as the sheet's today, with the pool, its
695	   695	     *  members, the pot and the holds as they were then); none when there was none. */
696	   696	    public record PeriodCut(String period, String cut) {
697	   697	    }
698	   698	
699	   699	    /** A pool, with its total share and whether that is exactly 100.00. A crew is a pool too (crew set): its id is
700	   700	     *  the crew's id negated, its members its lead and then its members, at equal shares. */
701	   701	    public record PoolView(long id, String name, List<PoolMemberView> members, String totalShare, boolean balanced,
702	   702	            boolean crew) {
703	   703	
704	   704	        /** The sheet's pools as views, in their order. A pool that is a member of another has as its pot its cut
705	   705	         *  in the pool above (none when that is unbalanced or has none); one that is a member of none has the
706	   706	         *  sheet's pot. A person on hold on the sheet's today gets no cut from any pool. The crews follow, each a
707	   707	         *  pool of the sheet's pot. */
708	   708	        static List<PoolView> of(List<Pool> pools, List<Crew> crews, Map<Long, Person> people, BigDecimal sheetPot,
709	   709	                LocalDate today) {
710	   710	            Map<Long, Pool> byId = new HashMap<>();
711	   711	            Map<Long, Pool> parentOf = new HashMap<>();
712	   712	            for (Pool pool : pools) {
713	   713	                byId.put(pool.getId(), pool);
714	   714	                for (PoolMember m : pool.getMembers()) {
715	   715	                    if (m.getMemberPoolId() != null) {
716	   716	                        parentOf.put(m.getMemberPoolId(), pool);
717	   717	                    }
718	   718	                }
719	   719	            }
720	   720	            Map<Long, PoolView> views = new HashMap<>();
721	   721	            for (Pool pool : pools) {
722	   722	                view(pool, byId, parentOf, people, sheetPot, today, views);
723	   723	            }
724	   724	            List<PoolView> out = new ArrayList<>(pools.stream().map(p -> views.get(p.getId())).toList());
725	   725	            for (Crew crew : crews) {
726	   726	                PoolView v = of(crewPool(crew), byId, people, sheetPot, today);
727	   727	                out.add(new PoolView(-crew.getId(), v.name(), v.members(), v.totalShare(), v.balanced(), true));
728	   728	            }
729	   729	            return out;
730	   730	        }
731	   731	
732	   732	        /** A crew as a pool: its lead (when it has one) and then its members, 100.00 split equally between them,
733	   733	         *  each rounded half to even to two decimals, the remainder on the first; none when it has no one. */
734	   734	        private static Pool crewPool(Crew crew) {
735	   735	            Pool pool = new Pool(crew.getSheetId(), crew.getName());
736	   736	            List<Long> ids = new ArrayList<>();
737	   737	            if (crew.getLeadId() != null) {
738	   738	                ids.add(crew.getLeadId());
739	   739	            }
740	   740	            crew.getMembers().forEach(m -> ids.add(m.getPersonId()));
741	   741	            if (ids.isEmpty()) {
742	   742	                return pool;
743	   743	            }
744	   744	            BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(ids.size()), 2, RoundingMode.HALF_EVEN);
745	   745	            BigDecimal lead = HUNDRED.subtract(each.multiply(BigDecimal.valueOf(ids.size() - 1)));
746	   746	            for (int i = 0; i < ids.size(); i++) {
747	   747	                pool.addMember(ids.get(i), i == 0 ? lead : each, null, null);
748	   748	            }
749	   749	            return pool;
750	   750	        }
751	   751	
752	   752	        private static PoolView view(Pool pool, Map<Long, Pool> byId, Map<Long, Pool> parentOf,
753	   753	                Map<Long, Person> people, BigDecimal sheetPot, LocalDate today, Map<Long, PoolView> views) {
754	   754	            PoolView done = views.get(pool.getId());
755	   755	            if (done != null) {
756	   756	                return done;
757	   757	            }
758	   758	            BigDecimal pot = sheetPot;
759	   759	            Pool parent = parentOf.get(pool.getId());
760	   760	            if (parent != null) {
761	   761	                PoolView above = view(parent, byId, parentOf, people, sheetPot, today, views);
762	   762	                String cut = above.members().stream().filter(m -> pool.getId().equals(m.poolId())).findFirst()
763	   763	                        .map(PoolMemberView::cut).orElse(null);
764	   764	                pot = cut == null ? null : new BigDecimal(cut);
765	   765	            }
766	   766	            PoolView v = of(pool, byId, people, pot, today);
767	   767	            views.put(pool.getId(), v);
768	   768	            return v;
769	   769	        }
770	   770	
771	   771	        private static PoolView of(Pool pool, Map<Long, Pool> pools, Map<Long, Person> people, BigDecimal pot,
772	   772	                LocalDate today) {
773	   773	            List<PoolMember> all = pool.getMembers();
774	   774	            BigDecimal total = BigDecimal.ZERO.setScale(2);
775	   775	            boolean[] retired = new boolean[all.size()];
776	   776	            boolean[] held = new boolean[all.size()];
777	   777	            boolean[] active = new boolean[all.size()];
778	   778	            boolean allRetired = true;
779	   779	            for (int i = 0; i < all.size(); i++) {
780	   780	                Long personId = all.get(i).getPersonId();
781	   781	                Person p = personId == null ? null : people.get(personId);
782	   782	                retired[i] = p != null && p.isRetired();
783	   783	                held[i] = p != null && today != null && p.heldOn(today);
784	   784	                active[i] = today == null || all.get(i).activeOn(today);
785	   785	                if (active[i]) {
786	   786	                    total = total.add(all.get(i).getShare());
787	   787	                    allRetired &= retired[i];
788	   788	                }
789	   789	            }
790	   790	            boolean balanced = total.compareTo(HUNDRED) == 0;
791	   791	            BigDecimal[] cuts = balanced && pot != null && !allRetired ? cuts(all, retired, held, active, pot) : new BigDecimal[all.size()];
792	   792	            List<PoolMemberView> members = new ArrayList<>();
793	   793	            for (int i = 0; i < all.size(); i++) {
794	   794	                PoolMember m = all.get(i);
795	   795	                String name;
796	   796	                if (m.getMemberPoolId() != null) {
797	   797	                    Pool member = pools.get(m.getMemberPoolId());
798	   798	                    name = member == null ? "" : member.getName();
799	   799	                } else {
800	   800	                    Person p = people.get(m.getPersonId());
801	   801	                    name = p == null ? "" : p.getName();
802	   802	                }
803	   803	                members.add(new PoolMemberView(m.getPersonId(), m.getMemberPoolId(), name,
804	   804	                        m.getShare().setScale(2).toPlainString(), retired[i],
805	   805	                        cuts[i] == null ? null : cuts[i].toPlainString(), m.getFromDate(), m.getToDate(),
806	   806	                        active[i], List.of()));
807	   807	            }
808	   808	            return new PoolView(pool.getId() == null ? 0 : pool.getId(), pool.getName(), members,
809	   809	                    total.setScale(2).toPlainString(), balanced, false);
810	   810	        }
811	   811	
812	   812	        /** Each member's cut of the pot: the pot times their share divided by the shares of the members with a
813	   813	         *  cut added up, rounded half to even to two decimals (0.00 for a retired one or one on hold, whose share is
814	   814	         *  spread over the others in proportion to theirs); the
815	   815	         *  remainder, the pot minus the cuts added up, goes to the member with the smallest non-zero cut, the
816	   816	         *  latest added on a tie (when no cut is non-zero, to the last member with a cut and a share), so the cuts
817	   817	         *  total exactly the pot. When no member has a cut, each is 0.00.
818	   818	         *  A member not active on the sheet's today has none at all. */
819	   819	        private static BigDecimal[] cuts(List<PoolMember> members, boolean[] retired, boolean[] held,
820	   820	                boolean[] active, BigDecimal pot) {
821	   821	            BigDecimal[] cuts = new BigDecimal[members.size()];
822	   822	            BigDecimal shares = BigDecimal.ZERO;
823	   823	            for (int i = 0; i < members.size(); i++) {
824	   824	                if (active[i] && !retired[i] && !held[i]) {
825	   825	                    shares = shares.add(members.get(i).getShare());
826	   826	                }
827	   827	            }
828	   828	            BigDecimal sum = BigDecimal.ZERO.setScale(2);
829	   829	            int smallest = -1;
830	   830	        int last = -1;
831	   831	            for (int i = 0; i < members.size(); i++) {
832	   832	                if (!active[i]) {
833	   833	                    continue;
834	   834	                }
835	   835	                BigDecimal share = members.get(i).getShare();
836	   836	                boolean cut = !retired[i] && !held[i] && shares.signum() > 0;
837	   837	                cuts[i] = cut ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
838	   838	                        : BigDecimal.ZERO.setScale(2);
839	   839	                sum = sum.add(cuts[i]);
840	   840	                if (cut && share.signum() > 0) {
841	   841	                    last = i;
842	   842	                }
843	   843	                if (cut && cuts[i].signum() != 0
844	   844	                        && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
845	   845	                    smallest = i;
846	   846	                }
847	   847	            }
848	   848	            int to = smallest >= 0 ? smallest : last;
849	   849	            if (to >= 0) {
850	   850	                cuts[to] = cuts[to].add(pot.setScale(2).subtract(sum));
851	   851	            }
852	   852	            return cuts;
