1299	  1299	    /** Refuse making a pool a member of another when it would contain itself, is already a member of a pool,
1300	  1300	     *  or the chain of pools would be more than three deep. */
1301	  1301	    private void refuseMemberPool(String sheetId, Pool pool, Pool member) {
1302	  1302	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
1303	  1303	        Map<Long, Long> parentOf = new HashMap<>();
1304	  1304	        for (Pool p : all) {
1305	  1305	            for (PoolMember m : p.getMembers()) {
1306	  1306	                if (m.getMemberPoolId() != null) {
1307	  1307	                    parentOf.put(m.getMemberPoolId(), p.getId());
1308	  1308	                }
1309	  1309	            }
1310	  1310	        }
1311	  1311	        int levelsAbove = 0;
1312	  1312	        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
1313	  1313	            if (at.equals(member.getId())) {
1314	  1314	                throw new PoolRefusedException(member.getName() + " cannot contain itself.");
1315	  1315	            }
1316	  1316	            levelsAbove++;
1317	  1317	        }
1318	  1318	        Long above = parentOf.get(member.getId());
1319	  1319	        if (above != null) {
1320	  1320	            String in = all.stream().filter(p -> p.getId().equals(above)).map(Pool::getName).findFirst().orElse("");
1321	  1321	            throw new PoolRefusedException(member.getName() + " is already in " + in + ".");
1322	  1322	        }
1323	  1323	        if (levelsAbove + depth(member, all) > MAX_DEPTH) {
1324	  1324	            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep.");
1325	  1325	        }
1326	  1326	    }
1327	  1327	
1328	  1328	    /** How many levels of pools a pool heads: 1, and the deepest of the pools in it. */
1329	  1329	    private static int depth(Pool pool, List<Pool> all) {
1330	  1330	        int below = 0;
1331	  1331	        for (PoolMember m : pool.getMembers()) {
1332	  1332	            if (m.getMemberPoolId() != null) {
1333	  1333	                Pool child = all.stream().filter(p -> p.getId().equals(m.getMemberPoolId())).findFirst().orElse(null);
1334	  1334	                if (child != null) {
1335	  1335	                    below = Math.max(below, depth(child, all));
1336	  1336	                }
1337	  1337	            }
1338	  1338	        }
1339	  1339	        return 1 + below;
1340	  1340	    }
