314	   314	package net.officefloor.hq.app.role;
315	   315	
316	   316	import java.time.LocalDate;
317	   317	import java.util.List;
318	   318	import net.officefloor.hq.app.Audit;
319	   319	import net.officefloor.hq.app.sheet.Sheet;
320	   320	import net.officefloor.hq.app.sheet.SheetNotFoundException;
321	   321	import net.officefloor.hq.app.sheet.SheetRepository;
322	   322	import org.springframework.dao.DataIntegrityViolationException;
323	   323	import org.springframework.stereotype.Service;
324	   324	import org.springframework.transaction.annotation.Transactional;
325	   325	
326	   326	/** Keeps the role each sheet gives a user name: clerk (any name with none), steward or viewer; and the
327	   327	 *  delegations of the steward role, under which a user acts as a steward while the sheet's today is in range. */
328	   328	@Service
329	   329	public class RoleService {
330	   330	
331	   331	    private final SheetRoleRepository roles;
332	   332	    private final DelegationRepository delegations;
333	   333	    private final SheetRepository sheets;
334	   334	    private final Audit audit;
335	   335	
336	   336	    public RoleService(SheetRoleRepository roles, DelegationRepository delegations, SheetRepository sheets,
337	   337	            Audit audit) {
338	   338	        this.roles = roles;
339	   339	        this.delegations = delegations;
340	   340	        this.sheets = sheets;
341	   341	        this.audit = audit;
342	   342	    }
343	   343	
344	   344	    @Transactional(readOnly = true)
345	   345	    public List<SheetRole> list(String sheetId) {
346	   346	        requireSheet(sheetId);
347	   347	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
348	   348	    }
349	   349	
350	   350	    /** Give a user name a role on the sheet, replacing the one it had. */
351	   351	    @Transactional
352	   352	    public SheetRole set(String sheetId, String user, String name, String role) {
353	   353	        requireSheet(sheetId);
354	   354	        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
355	   355	        if (row == null) {
356	   356	            try {
357	   357	                row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
358	   358	            } catch (DataIntegrityViolationException e) {
359	   359	                throw new RoleConflictException();
360	   360	            }
361	   361	        } else {
362	   362	            row.setRole(role);
363	   363	            row = roles.saveAndFlush(row);
364	   364	        }
365	   365	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role);
366	   366	        return row;
367	   367	    }
368	   368	
369	   369	    @Transactional(readOnly = true)
370	   370	    public List<Delegation> delegations(String sheetId) {
371	   371	        requireSheet(sheetId);
372	   372	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
373	   373	    }
374	   374	
375	   375	    /** A steward delegates the steward role to a user name from a date (none: the sheet's today) to a date
376	   376	     *  (none: the from-date), inclusive. Anyone but a steward is refused, as is a to-date before the from-date. */
377	   377	    @Transactional
378	   378	    public Delegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
379	   379	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
380	   380	        if (!hasStewardRole(sheetId, user)) {
381	   381	            throw new DelegationRefusedException("Only a steward may delegate the steward role.");
382	   382	        }
383	   383	        LocalDate start = from == null ? sheet.getToday() : from;
384	   384	        LocalDate end = to == null ? start : to;
385	   385	        if (end.isBefore(start)) {
386	   386	            throw new DelegationRefusedException("The to-date may not be before the from-date.");
387	   387	        }
388	   388	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, user, name, start, end));
389	   389	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + name
390	   390	                + " from=" + start + " to=" + end);
391	   391	        return saved;
392	   392	    }
393	   393	
394	   394	    /** Whether the sheet makes the user name a steward: given the role, or delegated it for the sheet's today. */
395	   395	    @Transactional(readOnly = true)
396	   396	    public boolean isSteward(String sheetId, String name) {
397	   397	        return hasStewardRole(sheetId, name) || delegatorOf(sheetId, name) != null;
398	   398	    }
399	   399	
400	   400	    /** The steward the user acts for: the one who delegated them the steward role for the sheet's today, when
401	   401	     *  they are not a steward themselves; none otherwise. */
402	   402	    @Transactional(readOnly = true)
403	   403	    public String actingFor(String sheetId, String name) {
404	   404	        return hasStewardRole(sheetId, name) ? null : delegatorOf(sheetId, name);
405	   405	    }
406	   406	
407	   407	    private boolean hasStewardRole(String sheetId, String name) {
408	   408	        return roles.findBySheetIdAndUserName(sheetId, name)
409	   409	                .map(r -> SheetRole.STEWARD.equals(r.getRole()))
410	   410	                .orElse(false);
411	   411	    }
412	   412	
413	   413	    /** The latest delegator of the steward role to the user covering the sheet's today; none when none does. */
414	   414	    private String delegatorOf(String sheetId, String name) {
415	   415	        List<Delegation> given = delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, name);
416	   416	        if (given.isEmpty()) {
417	   417	            return null;
418	   418	        }
419	   419	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
420	   420	        if (today == null) {
421	   421	            return null;
422	   422	        }
423	   423	        return given.stream().filter(d -> d.covers(today)).map(Delegation::getDelegator).findFirst().orElse(null);
424	   424	    }
425	   425	
426	   426	    /** Whether the sheet makes the user name a viewer, who sees the sheet and changes nothing; a user delegated
427	   427	     *  the steward role acts as a steward. */
428	   428	    @Transactional(readOnly = true)
429	   429	    public boolean isViewer(String sheetId, String name) {
430	   430	        if (delegatorOf(sheetId, name) != null) {
431	   431	            return false;
432	   432	        }
433	   433	        return roles.findBySheetIdAndUserName(sheetId, name)
434	   434	                .map(r -> SheetRole.VIEWER.equals(r.getRole()))
435	   435	                .orElse(false);
436	   436	    }
437	   437	
438	   438	    /** Refuse any change by a viewer. */
439	   439	    public void requireNotViewer(String sheetId, String name) {
440	   440	        if (isViewer(sheetId, name)) {
441	   441	            throw new ActionNotAllowedException("change anything");
442	   442	        }
443	   443	    }
444	   444	
445	   445	    /** Whether the user's role on the sheet may take an action, by the sheet's permission matrix (an action
446	   446	     *  with no roles set keeps the standing rule). */
447	   447	    @Transactional(readOnly = true)
448	   448	    public boolean allows(String sheetId, String name, String action) {
449	   449	        if (isViewer(sheetId, name)) {
450	   450	            return false;
451	   451	        }
452	   452	        String role = isSteward(sheetId, name) ? SheetRole.STEWARD : SheetRole.CLERK;
453	   453	        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).allows(action, role);
454	   454	    }
455	   455	
456	   456	    /** Refuse an action the user's role on the sheet may not take. */
457	   457	    public void require(String sheetId, String name, String action) {
458	   458	        if (!allows(sheetId, name, action)) {
459	   459	            throw new ActionNotAllowedException(action);
460	   460	        }
461	   461	    }
462	   462	
463	   463	    private void requireSheet(String sheetId) {
464	   464	        if (!sheets.existsById(sheetId)) {
465	   465	            throw new SheetNotFoundException();
466	   466	        }
467	   467	    }
468	   468	}
