556	   556	/**
557	   557	 * A viewer sees the sheet and changes nothing: every change to a sheet by a viewer is refused before it
558	   558	 * reaches its handler. Loading the sheet is not a change, and a bulk action goes through with nothing done
559	   559	 * (each claim refused, no one graded or retired, no plan claim made), so those are left to their handlers.
560	   560	 */
561	   561	@Configuration
562	   562	public class ViewerGuard implements WebMvcConfigurer, HandlerInterceptor {
563	   563	
564	   564	    private final RoleService roles;
565	   565	
566	   566	    public ViewerGuard(RoleService roles) {
567	   567	        this.roles = roles;
568	   568	    }
569	   569	
570	   570	    @Override
571	   571	    public void addInterceptors(InterceptorRegistry registry) {
572	   572	        registry.addInterceptor(this)
573	   573	                .addPathPatterns("/api/sheets/*/**")
574	   574	                .excludePathPatterns("/api/sheets/*/load", "/api/sheets/*/claims/bulk-*",
575	   575	                        "/api/sheets/*/people/bulk-grade", "/api/sheets/*/people/bulk-retire",
576	   576	                        "/api/sheets/*/plans/generate");
577	   577	    }
578	   578	
579	   579	    @Override
580	   580	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
581	   581	        if ("GET".equals(request.getMethod()) || "HEAD".equals(request.getMethod())
582	   582	                || "OPTIONS".equals(request.getMethod())) {
583	   583	            return true;
584	   584	        }
585	   585	        String user = request.getHeader("X-User");
586	   586	        @SuppressWarnings("unchecked")
587	   587	        Map<String, String> vars = (Map<String, String>) request
588	   588	                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
589	   589	        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
590	   590	        if (user != null && sheetId != null) {
591	   591	            roles.requireNotViewer(sheetId.trim(), user.trim());
592	   592	        }
593	   593	        return true;
594	   594	    }
595	   595	}
